INSERT INTO `backgrounds` (`background_id`, `background_name`, `background_desc`, `ability_scores`, `feat_id`, `skill_proficiencies`, `tool_proficiencies`, `equipment`, `srd_source`, `is_homebrew`, `author_id`, `deleted_at`, `modifiers`) VALUES
('acolyte', 'Acolyte', '<p>คุณอุทิศตนเพื่อรับใช้ในวิหาร ไม่ว่าจะตั้งอยู่ใจกลางเมืองอันพลุกพล่านหรือซ่อนเร้นอยู่ในป่าศักดิ์สิทธิ์ ที่นั่นคุณประกอบพิธีกรรมเพื่อเป็นเกียรติแก่เทพเจ้าหรือเหล่าทวยเทพ คุณรับใช้ภายใต้การดูแลของนักบวชและศึกษาคัมภีร์ศาสนา ด้วยคำสอนของนักบวชและความศรัทธาอันแรงกล้าของคุณ คุณจึงได้เรียนรู้วิธีการถ่ายทอดพลังศักดิ์สิทธิ์เพื่อรับใช้สถานที่สักการะและผู้คนที่เข้ามาสวดอ้อนวอน</p>', '{\"logic\": {\"allowed_attributes\": [\"Intelligence\", \"Wisdom\", \"Charisma\"], \"modes\": [\"plus_two_one\", \"three_plus_one\"]}, \"display\": \"Intelligence, Wisdom, Charisma\"}', 'magic-initiate-cleric', '{\"logic\": {\"granted\": [\"Insight\", \"Religion\"]}, \"display\": \"Insight and Religion\"}', '{\"logic\": {\"granted\": [\"Calligrapher\'s Supplies\"]}, \"display\": \"Calligrapher\'s Supplies\"}', '{\"logic\": {\"gold\": 50, \"items\": [\"Calligrapher\'s Supplies\", \"Book (Prayers)\", \"Parchment (10 sheets)\", \"Robe\", \"Holy Symbol\"]}, \"display\": \"Calligrapher\'s Supplies, a Book (Prayers), 10 sheets of Parchment, a Robe, a Holy Symbol, and 50 GP\"}', 'SRD 5.2.1, Page 110', 0, NULL, NULL, '[{\"type\":\"proficiency\",\"sub_type\":\"skill\",\"target\":\"insight and religion\",\"value\":\"\"}]'),
('criminal', 'Criminal', '<p>คุณเรียนรู้ที่จะหาเงินในตรอกซอกซอยอันมืดมิด กรีดกระเป๋าหรือย่องเบาตามร้านค้า คุณอาจเคยเป็นส่วนหนึ่งของแก๊งโจรเล็กๆ ที่คอยระวังหลังให้กัน หรือบางทีคุณอาจเป็นหมาป่าเดียวดายที่ต้องเอาตัวรอดจากกิลด์โจรเจ้าถิ่นและเหล่าอาชญากรผู้เหี้ยมโหดกว่า</p>', '{\"logic\": {\"allowed_attributes\": [\"Dexterity\", \"Constitution\", \"Intelligence\"], \"modes\": [\"plus_two_one\", \"three_plus_one\"]}, \"display\": \"Dexterity, Constitution, Intelligence\"}', 'alert', '{\"logic\": {\"granted\": [\"Sleight of Hand\", \"Stealth\"]}, \"display\": \"Sleight of Hand and Stealth\"}', '{\"logic\": {\"granted\": [\"Thieves\' Tools\"]}, \"display\": \"Thieves\' Tools\"}', '{\"logic\": {\"gold\": 50, \"items\": [\"Thieves\' Tools\", \"Crowbar\", \"Dark Common Clothes\", \"Pouch\", \"Dagger\"]}, \"display\": \"Thieves\' Tools, a Crowbar, Dark Common Clothes, a Pouch, a Dagger, and 50 GP\"}', 'SRD 5.2.1, Page 111', 0, NULL, NULL, '[{\"type\":\"proficiency\",\"sub_type\":\"skill\",\"target\":\"sleight of hand and stealth\",\"value\":\"\"}]'),
('sage', 'Sage', '<p>คุณใช้เวลาในช่วงวัยเยาว์ไปกับการศึกษาตำนานและสรรพความรู้แห่งพหุภพ (Multiverse) คุณค้นคว้าเอกสารตัวเขียน ศึกษาคัมภีร์โบราณ และรับฟังผู้เชี่ยวชาญที่ยิ่งใหญ่ที่สุดในเรื่องที่คุณสนใจ ความพยายามอย่างไม่หยุดยั้งทำให้คุณกลายเป็นผู้เชี่ยวชาญในสาขาวิชาที่คุณศึกษา</p>', '{\"logic\": {\"allowed_attributes\": [\"Constitution\", \"Intelligence\", \"Wisdom\"], \"modes\": [\"plus_two_one\", \"three_plus_one\"]}, \"display\": \"Constitution, Intelligence, Wisdom\"}', 'magic-initiate-wizard', '{\"logic\": {\"granted\": [\"Arcana\", \"History\"]}, \"display\": \"Arcana and History\"}', '{\"logic\": {\"granted\": [\"Calligrapher\'s Supplies\"]}, \"display\": \"Calligrapher\'s Supplies\"}', '{\"logic\": {\"gold\": 50, \"items\": [\"Calligrapher\'s Supplies\", \"Book (History)\", \"Parchment (10 sheets)\", \"Pen\", \"Robe\"]}, \"display\": \"Calligrapher\'s Supplies, a Book (History), 10 sheets of Parchment, a Pen, a Robe, and 50 GP\"}', 'SRD 5.2.1', 0, NULL, NULL, '[{\"type\":\"proficiency\",\"sub_type\":\"skill\",\"target\":\"arcana and history\",\"value\":\"\"}]'),
('soldier', 'Soldier', '<p>คุณเริ่มฝึกฝนเพื่อการศึกสงครามตั้งแต่วัยเยาว์จนคุ้นเคยกับการพกพาอาวุธราวกับเป็นส่วนหนึ่งของเสื้อผ้า คุณอาจเคยสังกัดกองทัพหลวงประจำชาติ กองทหารรับจ้าง หรืออาจเป็นสมาชิกของกองกำลังอาสาสมัครท้องถิ่นที่สร้างชื่อเสียงโดดเด่นในสงครามครั้งล่าสุด</p>', '{\"logic\": {\"allowed_attributes\": [\"Strength\", \"Dexterity\", \"Constitution\"], \"modes\": [\"plus_two_one\", \"three_plus_one\"]}, \"display\": \"Strength, Dexterity, Constitution\"}', 'savage-attacker', '{\"logic\": {\"granted\": [\"Athletics\", \"Intimidation\"]}, \"display\": \"Athletics and Intimidation\"}', '{\"logic\": {\"choices\": [{\"amount\": 1, \"options\": [\"Any Gaming Set\"]}]}, \"display\": \"One Gaming Set of your choice\"}', '{\"logic\": {\"gold\": 50, \"items\": [\"Gaming Set (same as chosen)\", \"Spear\", \"Healer\'s Kit\", \"Tent\", \"Traveler\'s Clothes\"]}, \"display\": \"A Gaming Set (same as your chosen tool), a Spear, a Healer\'s Kit, a Tent, Traveler\'s Clothes, and 50 GP\"}', 'SRD 5.2.1, Page 114', 0, NULL, NULL, '[{\"type\":\"proficiency\",\"sub_type\":\"skill\",\"target\":\"athletics and intimidation\",\"value\":\"\"}]'),
('time_traveler', 'Time Traveler', '<p>คุณไม่ได้มาจากยุคสมัยนี้ คุณอาจมาจากอดีตอันล่มสลาย หรือจากอนาคตอันไกลโพ้นที่เวทมนตร์และเทคโนโลยีหลอมรวมเข้าด้วยกัน ไม่ว่าการข้ามเวลาของคุณจะเกิดจากอุบัติเหตุทางเวทมนตร์กาลเวลา (Chronurgy Magic) พรจากเทพเจ้าแห่งเวลา หรือโบราณวัตถุที่แตกหัก เป้าหมายของคุณในตอนนี้คือการเอาชีวิตรอดในยุคสมัยอันแปลกประหลาดนี้และหาทางกลับบ้าน... หรือบางที คุณอาจต้องเปลี่ยนแปลงอดีตเพื่อปกป้องอนาคตของคุณเอง</p>', '{\"logic\":{\"allowed_attributes\":[\"Intelligence\",\"Wisdom\"],\"modes\":[\"plus_two_one\",\"three_plus_one\"]},\"display\":\"Intelligence, Wisdom\"}', 'alert', '{\"logic\":{\"granted\":[\"History\",\"Arcana\"]},\"display\":\"History and Arcana\"}', '{\"logic\":{\"granted\":[\"Tinker\'s tools\",\"Primordial\"]},\"display\":\"Tinker\'s tools, Primordial\"}', '{\"logic\":{\"gold\":75,\"items\":[\"Clothes, Traveler\'s\",\"Ink Pen\",\"Book\",\"Tinker\'s Tools\"]},\"display\":\"Clothes, Traveler\'s, Ink Pen, Book, Tinker\'s Tools, 75 GP\"}', 'Custom', 1, NULL, NULL, '[{\"type\":\"proficiency\",\"sub_type\":\"skill\",\"target\":\"history and arcana\",\"value\":\"\"}]');
