INSERT INTO `feats` (`feat_id`, `feat_name`, `feat_type`, `prerequisite`, `feat_desc`, `stat_options`, `feat_choices`, `srd_source`, `is_homebrew`, `author_id`, `modifiers`, `deleted_at`) VALUES
('ability-score-improvement', 'Ability Score Improvement', 'General Feat', 'Level 4+', 'เพิ่ม Ability score ที่คุณเลือก 1 ค่าขึ้น 2 แต้ม หรือเพิ่ม Ability score ที่คุณเลือก 2 ค่าขึ้นค่าละ 1 แต้ม Feat นี้ไม่สามารถเพิ่ม Ability score ให้เกิน 20 ได้\n\n_Repeatable._ คุณสามารถเลือก Feat นี้ได้มากกว่าหนึ่งครั้ง', '{\"type\":\"asi\",\"points\":2,\"max\":20}', NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('alert', 'Alert', 'Origin Feat', 'None', 'คุณได้รับประโยชน์ดังต่อไปนี้\n\n_Initiative Proficiency._ เมื่อคุณทอยค่า Initiative คุณสามารถบวก Proficiency Bonus ของคุณลงในผลการทอยได้\n\n_Initiative Swap._ ทันทีหลังจากคุณทอย Initiative คุณสามารถสลับค่า Initiative ของคุณกับ Initiative ของพันธมิตรที่ยินยอมหนึ่งคนในการต่อสู้เดียวกันได้ คุณไม่สามารถทำการสลับนี้ได้หากคุณหรือพันธมิตรติดสถานะ Incapacitated', NULL, NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"attack\",\"target\":\"initiative\",\"value\":\"prof\"}]', NULL),
('archery', 'Archery', 'Fighting Style Feat', 'Fighting Style Feature', 'คุณได้รับโบนัส +2 ในการทอยโจมตีเมื่อใช้อาวุธระยะไกล (Ranged weapons)', NULL, NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('boon-of-combat-prowess', 'Boon of Combat Prowess', 'Epic Boon Feat', 'Level 19+', 'คุณได้รับประโยชน์ดังต่อไปนี้\n\n_Ability Score Increase._ เพิ่ม Ability score ที่คุณเลือก 1 ค่าขึ้น 1 แต้ม สูงสุดไม่เกิน 30\n\n_Peerless Aim._ เมื่อคุณทอยโจมตีพลาด คุณสามารถเลือกให้การโจมตีนั้นกลายเป็นการโจมตีโดนได้ เมื่อใช้ความสามารถนี้แล้ว คุณจะไม่สามารถใช้ได้อีกจนกว่าจะถึงจุดเริ่มต้นของเทิร์นถัดไปของคุณ', '{\"type\":\"half\",\"choices\":[\"str\",\"dex\",\"con\",\"int\",\"wis\",\"cha\"],\"points\":1,\"max\":30}', NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('boon-of-dimensional-travel', 'Boon of Dimensional Travel', 'Epic Boon Feat', 'Level 19+', 'คุณได้รับประโยชน์ดังต่อไปนี้\n\n_Ability Score Increase._ เพิ่ม Ability score ที่คุณเลือก 1 ค่าขึ้น 1 แต้ม สูงสุดไม่เกิน 30\n\n_Blink Steps._ ทันทีหลังจากคุณใช้ Attack action หรือ Magic action คุณสามารถเทเลพอร์ตได้สูงสุด 30 ฟุตไปยังพื้นที่ว่างที่คุณมองเห็น', '{\"type\":\"half\",\"choices\":[\"str\",\"dex\",\"con\",\"int\",\"wis\",\"cha\"],\"points\":1,\"max\":30}', NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('boon-of-fate', 'Boon of Fate', 'Epic Boon Feat', 'Level 19+', 'คุณได้รับประโยชน์ดังต่อไปนี้\n\n_Ability Score Increase._ เพิ่ม Ability score ที่คุณเลือก 1 ค่าขึ้น 1 แต้ม สูงสุดไม่เกิน 30\n\n_Improve Fate._ เมื่อคุณหรือสิ่งมีชีวิตอื่นในระยะ 60 ฟุตทอย D20 Test สำเร็จหรือล้มเหลว คุณสามารถทอย 2d4 แล้วนำผลรวมที่ได้ไปบวกหรือลบผลการทอย d20 นั้นได้ เมื่อใช้ความสามารถนี้แล้ว คุณจะไม่สามารถใช้ได้อีกจนกว่าคุณจะทอย Initiative หรือสิ้นสุดการพักผ่อนแบบ Short Rest หรือ Long Rest', '{\"type\":\"half\",\"choices\":[\"str\",\"dex\",\"con\",\"int\",\"wis\",\"cha\"],\"points\":1,\"max\":30}', NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('boon-of-irresistible-offense', 'Boon of Irresistible Offense', 'Epic Boon Feat', 'Level 19+', 'คุณได้รับประโยชน์ดังต่อไปนี้\n\n_Ability Score Increase._ เพิ่มค่า Strength หรือ Dexterity ของคุณขึ้น 1 แต้ม สูงสุดไม่เกิน 30\n\n_Overcome Defenses._ ความเสียหายประเภท Bludgeoning, Piercing และ Slashing ที่คุณสร้างจะมองข้ามค่า Resistance เสมอ\n\n_Overwhelming Strike._ เมื่อคุณทอยได้หน้า 20 บนเต๋า d20 สำหรับการทอยโจมตี คุณสามารถสร้างความเสียหายเพิ่มเติมแก่เป้าหมายเท่ากับค่า Ability score ที่ได้รับการเพิ่มจาก Feat นี้ โดยประเภทความเสียหายจะเป็นประเภทเดียวกับการโจมตีนั้น', '{\"type\":\"half\",\"choices\":[\"str\",\"dex\"],\"points\":1,\"max\":30}', NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('boon-of-spell-recall', 'Boon of Spell Recall', 'Epic Boon Feat', 'Level 19+, Spellcasting Feature', 'คุณได้รับประโยชน์ดังต่อไปนี้\n\n_Ability Score Increase._ เพิ่มค่า Intelligence, Wisdom หรือ Charisma ของคุณขึ้น 1 แต้ม สูงสุดไม่เกิน 30\n\n_Free Casting._ เมื่อใดก็ตามที่คุณร่ายเวทมนตร์โดยใช้ช่องเวทมนตร์ (Spell slot) เลเวล 1–4 ให้ทอย 1d4 หากตัวเลขที่คุณทอยได้ตรงกับเลเวลของช่องเวทมนตร์นั้น ช่องเวทมนตร์ดังกล่าวจะไม่ถูกใช้ไป', '{\"type\":\"half\",\"choices\":[\"int\",\"wis\",\"cha\"],\"points\":1,\"max\":30}', NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('boon-of-the-night-spirit', 'Boon of the Night Spirit', 'Epic Boon Feat', 'Level 19+', 'คุณได้รับประโยชน์ดังต่อไปนี้\n\n_Ability Score Increase._ เพิ่ม Ability score ที่คุณเลือก 1 ค่าขึ้น 1 แต้ม สูงสุดไม่เกิน 30\n\n_Merge with Shadows._ ขณะอยู่ในแสงสลัว (Dim Light) หรือความมืด (Darkness) คุณสามารถทำให้ตนเองติดสถานะ Invisible ได้โดยใช้ Bonus Action โดยสถานะนี้จะสิ้นสุดลงทันทีหลังจากคุณใช้ Action, Bonus Action หรือ Reaction\n\n_Shadowy Form._ ขณะอยู่ในแสงสลัวหรือความมืด คุณได้รับ Resistance ต่อความเสียหายทุกชนิดยกเว้น Psychic และ Radiant', '{\"type\":\"half\",\"choices\":[\"str\",\"dex\",\"con\",\"int\",\"wis\",\"cha\"],\"points\":1,\"max\":30}', NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('boon-of-truesight', 'Boon of Truesight', 'Epic Boon Feat', 'Level 19+', 'คุณได้รับประโยชน์ดังต่อไปนี้\n\n_Ability Score Increase._ เพิ่ม Ability score ที่คุณเลือก 1 ค่าขึ้น 1 แต้ม สูงสุดไม่เกิน 30\n\n_Truesight._ คุณมีสายตาแบบ Truesight ในระยะ 60 ฟุต', '{\"type\":\"half\",\"choices\":[\"str\",\"dex\",\"con\",\"int\",\"wis\",\"cha\"],\"points\":1,\"max\":30}', NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('defense', 'Defense', 'Fighting Style Feat', 'Fighting Style Feature', 'ขณะที่คุณสวมใส่ชุดเกราะเบา (Light), ชุดเกราะปานกลาง (Medium) หรือชุดเกราะหนัก (Heavy) คุณจะได้รับโบนัส +1 ให้กับ Armor Class (AC)', NULL, NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('grappler', 'Grappler', 'General Feat', 'Level 4+, Strength or Dexterity 13+', 'คุณได้รับประโยชน์ดังต่อไปนี้\n\n_Ability Score Increase._ เพิ่มค่า Strength หรือ Dexterity ของคุณขึ้น 1 แต้ม สูงสุดไม่เกิน 20\n\n_Punch and Grab._ เมื่อคุณโจมตีสิ่งมีชีวิตโดนด้วย Unarmed Strike ซึ่งเป็นส่วนหนึ่งของ Attack action ในเทิร์นของคุณ คุณสามารถใช้ทั้งผลสร้างความเสียหาย (Damage) และการจับยึด (Grapple) พร้อมกันได้ คุณสามารถใช้ประโยชน์นี้ได้เพียงครั้งเดียวต่อเทิร์น\n\n_Attack Advantage._ คุณได้รับ Advantage ในการทอยโจมตีต่อสิ่งมีชีวิตที่ถูกคุณ Grappled อยู่\n\n_Fast Wrestler._ คุณไม่จำเป็นต้องเสียระยะการเคลื่อนที่เพิ่มเติมในการลากสิ่งมีชีวิตที่คุณ Grappled ไว้ หากสิ่งมีชีวิตนั้นมีขนาดเท่ากับคุณหรือเล็กกว่า', '{\"type\":\"half\",\"choices\":[\"str\",\"dex\"],\"points\":1,\"max\":20}', NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('great-weapon-fighting', 'Great Weapon Fighting', 'Fighting Style Feat', 'Fighting Style Feature', 'เมื่อคุณทอยความเสียหายสำหรับการโจมตีด้วยอาวุธระยะประชิด (Melee weapon) ที่คุณถือด้วยสองมือ คุณสามารถเปลี่ยนผลลูกเต๋าความเสียหายที่เป็น 1 หรือ 2 ให้กลายเป็น 3 ได้ โดยอาวุธนั้นจะต้องมีคุณสมบัติ Two-Handed หรือ Versatile จึงจะได้รับประโยชน์นี้', NULL, NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('magic-initiate', 'Magic Initiate', 'Origin Feat', 'None', 'คุณได้รับประโยชน์ดังต่อไปนี้\n\n_Two Cantrips._ คุณได้เรียนรู้เวทมนตร์ Cantrip จำนวน 2 บทจากรายชื่อเวทมนตร์ของ Cleric, Druid หรือ Wizard โดยใช้ Intelligence, Wisdom หรือ Charisma เป็นความสามารถในการร่ายเวทมนตร์ (Spellcasting Ability) สำหรับ Feat นี้ (เลือกเมื่อคุณได้รับ Feat นี้)\n\n_Level 1 Spell._ เลือกเวทมนตร์เลเวล 1 จำนวน 1 บทจากรายชื่อเดียวกันกับที่คุณเลือก Cantrip คุณจะมีเวทมนตร์นั้นเตรียมไว้เสมอ คุณสามารถร่ายได้ 1 ครั้งโดยไม่ต้องใช้ช่องเวทมนตร์ และคุณจะฟื้นฟูสิทธิ์ในการร่ายด้วยวิธีนี้เมื่อพักผ่อนแบบ Long Rest คุณยังสามารถร่ายเวทมนตร์นี้โดยใช้ช่องเวทมนตร์ที่มีอยู่ได้ด้วย\n\n_Spell Change._ เมื่อใดก็ตามที่คุณเลเวลอัป คุณสามารถเปลี่ยนเวทมนตร์บทใดบทหนึ่งที่เลือกจาก Feat นี้เป็นเวทมนตร์อื่นในเลเวลเดียวกันจากรายชื่อเดิมได้\n\n_Repeatable._ คุณสามารถเลือก Feat นี้ได้มากกว่าหนึ่งครั้ง แต่ต้องเลือกรายชื่อเวทมนตร์ที่ต่างกันในแต่ละครั้ง', NULL, NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('savage-attacker', 'Savage Attacker', 'Origin Feat', 'None', 'คุณได้รับการฝึกฝนให้โจมตีได้อย่างรุนแรงเป็นพิเศษ หนึ่งครั้งต่อเทิร์นเมื่อคุณโจมตีเป้าหมายโดนด้วยอาวุธ คุณสามารถทอยลูกเต๋าความเสียหายของอาวุธสองครั้งและเลือกใช้ผลการทอยใดอันหนึ่งได้', NULL, NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('skilled', 'Skilled', 'Origin Feat', 'None', 'คุณได้รับความชำนาญ (Proficiency) ในทักษะ (Skills) หรือชุดเครื่องมือ (Tools) ใดๆ รวมกัน 3 ชนิดตามที่คุณเลือก\n\n_Repeatable._ คุณสามารถเลือก Feat นี้ได้มากกว่าหนึ่งครั้ง', NULL, NULL, NULL, 0, NULL, '[{\"type\":\"proficiency\",\"sub_type\":\"skill\",\"target\":\"choice\",\"value\":\"3\"}]', NULL),
('time-touched', 'Time-Touched', 'Origin Feat', 'None', 'คุณได้รับประโยชน์ดังต่อไปนี้:\n\n_Echoes of Another Era._ คุณได้รับความชำนาญ (Proficiency) ในทักษะ (Skill) หรือเครื่องมือ (Tool) 1 ชนิดตามที่คุณเลือก\n\n_Minor Rewind._ เมื่อคุณหรือสิ่งมีชีวิตที่คุณมองเห็นในระยะ 30 ฟุตทอย Ability Check หรือ Saving Throw ล้มเหลว คุณสามารถใช้ Reaction เพื่อทอย 1d4 และนำผลไปบวกเพิ่มในผลลัพธ์ได้ คุณสามารถใช้ความสามารถนี้ได้เท่ากับจำนวนครั้งของ Proficiency Bonus ของคุณ และจะฟื้นฟูการใช้งานทั้งหมดเมื่อพักผ่อนแบบ Long Rest\n\n_Temporal Mending._ คุณได้เรียนรู้เวทมนตร์ Cantrip คาถา Mending', NULL, NULL, 'Custom Homebrew', 1, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL),
('two-weapon-fighting', 'Two-Weapon Fighting', 'Fighting Style Feat', 'Fighting Style Feature', 'เมื่อคุณทำการโจมตีเพิ่มเติมอันเป็นผลมาจากการใช้อาวุธที่มีคุณสมบัติ Light คุณสามารถบวกค่า Ability modifier ของคุณลงในความเสียหายของการโจมตีนั้นได้ หากคุณยังไม่ได้บวกมันลงไป', NULL, NULL, NULL, 0, NULL, '[{\"type\":\"bonus\",\"sub_type\":\"stat\",\"target\":\"strength\",\"value\":\"1\"}]', NULL);
