INSERT INTO `items` (`item_id`, `item_name`, `image_url`, `item_type`, `subcategory`, `rarity`, `cost`, `weight`, `attunement`, `damage`, `mastery`, `properties`, `ac`, `strength_req`, `stealth`, `item_desc`, `mechanics`, `srd_source`, `is_homebrew`, `author_id`, `deleted_at`) VALUES
('acid', 'Acid', NULL, 'Gear', NULL, 'None', '25 GP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'เมื่อคุณใช้แอ็กชัน Attack คุณสามารถสละการโจมตีหนึ่งครั้งเพื่อขว้างขวด Acid ใส่สิ่งมีชีวิตหรือวัตถุที่คุณมองเห็นในระยะ 20 ฟุต เป้าหมายต้องผ่านการทอยเซฟ Dexterity (DC 8 + ตัวปรับแต่ง Dexterity ของคุณ + Proficiency Bonus ของคุณ) มิฉะนั้นจะได้รับความเสียหาย Acid 2d6', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('acid-vial', 'Acid (vial)', NULL, 'Gear', 'Adventuring Gear', 'None', '25 GP', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>เมื่อคุณใช้แอ็กชัน Attack คุณสามารถสละการโจมตีหนึ่งครั้งเพื่อขว้างขวด Acid ใส่สิ่งมีชีวิตหรือวัตถุที่คุณมองเห็นในระยะ 20 ฟุต เป้าหมายต้องผ่านการทอยเซฟ Dexterity (DC 8 + ตัวปรับแต่ง Dex + PB) มิฉะนั้นจะได้รับความเสียหาย Acid 2d6</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 94', 0, NULL, NULL),
('adamantine-armor', 'Adamantine Armor', NULL, 'Magic Item', 'Armor', 'Uncommon', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>ชุดเกราะนี้ได้รับการเสริมความแข็งแกร่งด้วยแร่อดาแมนไทน์ (Adamantine) ซึ่งเป็นหนึ่งในสสารที่แข็งแกร่งที่สุดในเอกภพ ขณะที่คุณสวมใส่ชุดเกราะนี้ การโจมตีติดคริติคอล (Critical Hit) ใดๆ ที่กระทำต่อคุณจะกลายเป็นการโจมตีโดนแบบปกติ</p>', '{\"logic\":{\"stealth_disadvantage\":false,\"strength_requirement\":0},\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 209', 0, NULL, NULL),
('airship', 'Airship', NULL, 'Vehicle', 'Waterborne/Airborne Vehicle', 'None', '40,000 GP', '', '', '', '', 'Speed: 8 mph', '13', '', '', 'ความเร็ว (Speed): 8 ไมล์/ชม. | ลูกเรือ (Crew): 10 คน | ผู้โดยสาร (Passengers): 20 คน | บรรทุกสัมภาระ (Cargo): 1 ตัน | AC: 13 | HP: 300', '{\"logic\":{\"speed\":\"8 mph\",\"crew\":\"10\",\"passengers\":\"20\",\"cargo\":\"1\",\"ac\":\"13\",\"hp\":\"300\"},\"display\":\"Speed: 8 mph | AC: 13 | HP: 300\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('alchemists-fire', 'Alchemist\'s Fire (flask)', NULL, 'Gear', 'Adventuring Gear', 'None', '50 GP', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>เมื่อคุณใช้แอ็กชัน Attack คุณสามารถสละการโจมตีหนึ่งครั้งเพื่อขว้างขวด Alchemist\'s Fire ใส่เป้าหมายในระยะ 20 ฟุต เป้าหมายต้องทอยเซฟ Dex (DC 8 + Dex + PB) สำเร็จ มิฉะนั้นจะได้รับความเสียหาย Fire 1d4 และติดไฟต่อเนื่อง</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 94', 0, NULL, NULL),
('alchemists-supplies', 'Alchemist\'s Supplies', NULL, 'Tool', 'Artisan\'s Tools', 'None', '50 GP', '8', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p><b>ความสามารถ (Ability):</b> Intelligence<br><b>การใช้งาน (Utilize):</b> ระบุสารเคมีหรือของเหลว (DC 15) หรือจุดไฟ (DC 15)<br><b>การสร้าง (Craft):</b> Acid, Alchemist\'s Fire, Component Pouch, Oil, Paper, Perfume</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 93', 0, NULL, NULL),
('alchemists_supplies', 'Alchemist\'s Supplies', NULL, 'Tool', 'Tool', 'None', '50 GP', '8 lb.', '', '', '', 'Ability: Intelligence', '', '', '', '**ความสามารถ (Ability):** Intelligence\n\n**การใช้งาน (Utilize):** ระบุสารเคมีหรือของเหลว (DC 15) หรือจุดไฟ (DC 15)\n\n**การสร้าง (Craft):** Acid, Alchemist\'s Fire, Component Pouch, Oil, Paper, Perfume', '{\"logic\":{\"tool_type\":\"Tool\",\"ability\":\"Intelligence\",\"utilize\":\"Identify a substance (DC 15), or start a fire (DC 15)\",\"craft\":\"Acid, Alchemist\'s Fire, Component Pouch, Oil, Paper, Perfume\"},\"display\":\"Ability: Intelligence | Craft: Acid, Alchemist\'s Fire, Component Pouch, Oil, Paper, Perfume\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('alchemist_s_fire', 'Alchemist\'s Fire', NULL, 'Gear', NULL, 'None', '50 GP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'เมื่อคุณใช้แอ็กชัน Attack คุณสามารถสละการโจมตีหนึ่งครั้งเพื่อขว้างขวด Alchemist\'s Fire ใส่สิ่งมีชีวิตหรือวัตถุที่คุณมองเห็นในระยะ 20 ฟุต เป้าหมายต้องผ่านการทอยเซฟ Dexterity (DC 8 + ตัวปรับแต่ง Dexterity ของคุณ + Proficiency Bonus ของคุณ) มิฉะนั้นจะได้รับความเสียหาย Fire 1d4 และติดไฟลุกไหม้ (Burning) โดยจะได้รับความเสียหาย Fire 1d4 ในตอนเริ่มเทิร์นของมันจนกว่าจะมีผู้ใช้แอ็กชันดับไฟ (DC 10 Dexterity check)', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('ammunition', 'Ammunition', NULL, 'Gear', NULL, 'None', 'Varies', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'กระสุน (Ammunition) จำเป็นสำหรับการใช้อาวุธที่มีคุณสมบัติ Ammunition ในคำอธิบายของอาวุธจะระบุชนิดของกระสุนที่ต้องใช้ เช่น Arrows (ลูกธนูสำหรับธนู), Bolts (ดอกหน้าไม้สำหรับหน้าไม้), Bullets (ลูกกระสุนสำหรับสลิงหรือปืนคาบศิลา) และ Needles (ดอกเข็มสำหรับกระบอกเป่าลูกดอก)', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('ammunition-plus', 'Ammunition, +1, +2, or +3', NULL, 'Magic Item', 'Weapon', 'Varies', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>คุณจะได้รับโบนัสในการทอยโจมตีและการทอยความเสียหายเมื่อใช้กระสุนเวทมนตร์ชิ้นนี้ โดยโบนัสจะขึ้นอยู่กับระดับความหายาก (Uncommon: +1, Rare: +2, Very Rare: +3) เมื่อยิงโดนเป้าหมาย กระสุนนี้จะหมดฤทธิ์และกลายเป็นกระสุนธรรมดา</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 209', 0, NULL, NULL),
('ammunition_of_slaying', 'Ammunition of Slaying', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Weapon (Any Ammunition), Very Rare_\n\nกระสุนเวทมนตร์นี้สร้างขึ้นมาเพื่อสังหารสิ่งมีชีวิตเฉพาะประเภท ซึ่ง GM จะเป็นผู้เลือกหรือสุ่มจากตารางด้านล่าง หากสิ่งมีชีวิตประเภทดังกล่าวได้รับความเสียหายจากกระสุนนี้ สิ่งมีชีวิตนั้นต้องทอยเซฟ DC 17 Constitution หากล้มเหลวจะได้รับความเสียหาย Force เพิ่มเติมอีก 6d10 หรือกึ่งหนึ่งหากเซฟสำเร็จ\n\nหลังจากสร้างความเสียหายเพิ่มเติมแก่สิ่งมีชีวิตแล้ว กระสุนนี้จะสูญเสียพลังเวทมนตร์และกลายเป็นกระสุนธรรมดา\n\n<table>\n  <thead>\n    <tr>\n      <th>1d100</th>\n      <th>ประเภทสิ่งมีชีวิต</th>\n      <th>1d100</th>\n      <th>ประเภทสิ่งมีชีวิต</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td>01–10</td>\n      <td>Aberrations</td>\n      <td>51–60</td>\n      <td>Fey</td>\n    </tr>\n    <tr>\n      <td>11–15</td>\n      <td>Beasts</td>\n      <td>61–70</td>\n      <td>Fiends</td>\n    </tr>\n    <tr>\n      <td>16–20</td>\n      <td>Celestials</td>\n      <td>71–75</td>\n      <td>Giants</td>\n    </tr>\n    <tr>\n      <td>21–25</td>\n      <td>Constructs</td>\n      <td>76–80</td>\n      <td>Monstrosities</td>\n    </tr>\n    <tr>\n      <td>26–35</td>\n      <td>Dragons</td>\n      <td>81–85</td>\n      <td>Oozes</td>\n    </tr>\n    <tr>\n      <td>36–45</td>\n      <td>Elementals</td>\n      <td>86–90</td>\n      <td>Plants</td>\n    </tr>\n    <tr>\n      <td>46–50</td>\n      <td>Humanoids</td>\n      <td>91–00</td>\n      <td>Undead</td>\n    </tr>\n  </tbody>\n</table>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('amulet-of-health', 'Amulet of Health', NULL, 'Magic Item', 'Wondrous Item', 'Rare', NULL, '0', 'Requires Attunement', NULL, NULL, NULL, NULL, NULL, NULL, '<p>ค่าความทนทาน (Constitution) ของคุณจะกลายเป็น 19 ขณะที่คุณสวมเครื่องรางนี้ เครื่องรางจะไม่มีผลหากค่า Constitution ตามปกติของคุณเท่ากับหรือมากกว่า 19 อยู่แล้ว</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 209', 0, NULL, NULL),
('amulet_of_proof_against_detection_and_location', 'Amulet of Proof against Detection and Location', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon (Requires Attunement)_\n\nขณะสวมเครื่องรางนี้ คุณจะไม่ตกเป็นเป้าหมายของคาถาสาย Divination หรือถูกตรวจจับผ่านเซนเซอร์สอดแนมทางเวทมนตร์ (Scrying Sensors) ได้ เว้นแต่คุณจะยินยอมให้กระทำ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('amulet_of_the_planes', 'Amulet of the Planes', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Very Rare (Requires Attunement)_\n\nขณะสวมเครื่องรางนี้ คุณสามารถใช้แอ็กชัน Magic เพื่อระบุสถานที่ที่คุณคุ้นเคยบนมิติอื่น (Plane of Existence) จากนั้นให้ทอย DC 15 Intelligence check หากสำเร็จ คุณและสิ่งมีชีวิตทุกตัวในระยะ 15 ฟุตจะถูกเทเลพอร์ตไปยังสถานที่เป้าหมาย หากล้มเหลว คุณและสิ่งมีชีวิตในระยะจะถูกเทเลพอร์ตไปยังสถานที่แบบสุ่มบนมิติใดมิติหนึ่งตามการตัดสินของ GM', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('animated_shield', 'Animated Shield', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Armor (Shield), Very Rare (Requires Attunement)_\n\nขณะถือโล่นี้ คุณสามารถใช้โบนัสแอ็กชันเพื่อให้โล่ลอยทำงาน โล่จะลอยขึ้นไปในอากาศและลอยปกป้องคุณอยู่ในช่องของคุณ มอบโบนัส AC ของโล่ประหนึ่งว่าคุณกำลังถือมันอยู่ ทำให้มือทั้งสองข้างของคุณว่าง โล่จะลอยปกป้องคุณเป็นเวลา 1 นาที หรือจนกว่าคุณจะสั่งเก็บเป็นโบนัสแอ็กชัน หรือจนกว่าคุณจะตกอยู่ในสภาวะ Incapacitated หรือเสียชีวิต', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('antitoxin', 'Antitoxin (vial)', NULL, 'Gear', 'Adventuring Gear', 'None', '50 GP', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>คุณสามารถดื่มขวดยาแก้พิษ (Antitoxin) เป็นโบนัสแอ็กชันเพื่อรับ Advantage ในการทอยเซฟต้านสถานะ Poisoned และการทอยเซฟลดความเสียหาย Poison เป็นเวลา 1 ชั่วโมง</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 96', 0, NULL, NULL),
('apparatus_of_the_crab', 'Apparatus of the Crab', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Legendary_\n\nไอเทมชิ้นนี้ในตอนแรกดูเหมือนถังเหล็กปิดผนึกน้ำหนัก 500 ปอนด์ ถังมีสลักลับที่สามารถค้นพบได้ด้วย DC 20 Intelligence (Investigation) check เมื่อเปิดออกจะเผยให้เห็นห้องโดยสารขนาดสองที่นั่งสำหรับสิ่งมีชีวิตขนาด Medium หรือเล็กกว่า ภายในมีคันโยก 10 ตัวสำหรับบังคับยานจักรกลรูปปูนี้ ซึ่งสามารถดำน้ำลึก เดินบนพื้น และใช้ก้ามหนีบโจมตีศัตรูได้', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('arcane_focus', 'Arcane Focus', NULL, 'Gear', NULL, 'None', 'Varies', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'สื่อร่ายเวทมนตร์สายเวทอาร์เคน (Arcane Focus) อาจอยู่ในรูปของ Crystal, Orb, Rod, Staff หรือ Wand ออกแบบมาเพื่อเป็นสื่อเหนี่ยวนำพลังเวทมนตร์สำหรับนักเวท เช่น Sorcerer, Warlock หรือ Wizard แทนการใช้วัตถุดิบ Material ทั่วไปที่ไม่มีราคา', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('armor-plus', 'Armor, +1, +2, or +3', NULL, 'Magic Item', 'Armor', 'Varies', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>คุณจะได้รับโบนัส Armor Class (AC) เพิ่มขึ้นขณะสวมใส่ชุดเกราะเวทมนตร์นี้ โดยโบนัสจะขึ้นอยู่กับระดับความหายาก (Rare: +1, Very Rare: +2, Legendary: +3)</p>', '{\"logic\":{\"stealth_disadvantage\":false,\"strength_requirement\":0},\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 210', 0, NULL, NULL),
('armor_of_invulnerability', 'Armor of Invulnerability', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Armor (Plate Armor), Legendary (Requires Attunement)_\n\nคุณมีความต้านทาน (Resistance) ต่อความเสียหาย Bludgeoning, Piercing และ Slashing ที่ไม่ใช่เวทมนตร์ขณะสวมชุดเกราะนี้\n\n**_Metal Shell._** คุณสามารถใช้แอ็กชัน Magic เพื่อรับภูมิคุ้มกัน (Immunity) ต่อความเสียหายทุกชนิดเป็นเวลา 10 นาที หรือจนกว่าคุณจะถอดเกราะ คุณสมบัตินี้ใช้ได้วันละหนึ่งครั้ง และจะฟื้นฟูใหม่ในยามรุ่งอรุณถัดไป', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('armor_of_resistance', 'Armor of Resistance', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Armor (Any Light, Medium, or Heavy), Rare (Requires Attunement)_\n\nคุณมีความต้านทาน (Resistance) ต่อความเสียหายหนึ่งประเภทขณะสวมชุดเกราะนี้ โดย GM จะเป็นผู้เลือกหรือสุ่มประเภทความเสียหาย (Acid, Cold, Fire, Force, Lightning, Necrotic, Poison, Psychic, Radiant หรือ Thunder)', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('armor_of_vulnerability', 'Armor of Vulnerability', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Armor (Any Light, Medium, or Heavy), Rare (Requires Attunement)_\n\nขณะสวมเกราะนี้ คุณมีความต้านทาน (Resistance) ต่อความเสียหายหนึ่งประเภทจาก: Bludgeoning, Piercing หรือ Slashing แต่คุณจะติดคำสาปให้เกิดความอ่อนแอ (Vulnerability) ต่อความเสียหายอีกสองประเภทที่เหลือ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('arrow_catching_shield', 'Arrow-Catching Shield', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Armor (Shield), Rare (Requires Attunement)_\n\nคุณจะได้รับโบนัส +2 ใน Armor Class ต้านการโจมตีระยะไกล (Ranged Attacks) ขณะถือโล่นี้ (เพิ่มเติมนอกเหนือจากโบนัส AC ปกติของโล่) นอกจากนี้ เมื่อการโจมตีระยะไกลพุ่งเป้าไปที่เป้าหมายอื่นในระยะ 5 ฟุตจากคุณ คุณสามารถใช้ Reaction เพื่อให้การโจมตีนั้นเปลี่ยนเป้าหมายมาโจมตีที่คุณแทน', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('artisan_s_tools', 'Artisan\'s Tools', NULL, 'Tool', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'อุปกรณ์ช่างฝีมือ (Artisan\'s Tools) แต่ละประเภทเน้นการประดิษฐ์สิ่งของและการประกอบอาชีพเฉพาะทาง โดยอุปกรณ์แต่ละประเภทต้องการความชำนาญ (Proficiency) แยกกัน', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('attune_during_a_short_rest', 'Attune during a Short Rest', NULL, 'Gear', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'การผูกพันกับไอเทมเวทมนตร์ (Attunement) กำหนดให้คุณใช้เวลาในช่วง Short Rest เพื่อจดจ่ออยู่กับไอเทมชิ้นนั้นเพียงอย่างเดียวในขณะที่สัมผัสกับไอเทม เมื่อจบการพัก คุณจะผูกพันกับไอเทมและสามารถใช้งานคุณสมบัติเวทมนตร์ของมันได้', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('avatar_of_death', 'Avatar of Death', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Medium Undead, Neutral Evil_\n\n**AC** 20 **Initiative** +3 (13) <br>\n**HP** ครึ่งหนึ่งของ HP สูงสุดของผู้ที่อัญเชิญมันขึ้นมา <br>\n**Speed** 60 ฟุต, บิน 60 ฟุต (hover) <br>\n\nร่างอวตารแห่งความตายจะโจมตีเป้าหมายที่อัญเชิญมันขึ้นมาเท่านั้นจนกว่าฝ่ายใดฝ่ายหนึ่งจะตาย หากมีผู้ใดพยายามยื่นมือเข้ามาช่วย อวตารแห่งความตายอีกตนจะปรากฏขึ้นมาโจมตีบุคคลผู้นั้นโดยเฉพาะ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('backpack', 'Backpack', NULL, 'Gear', 'Adventuring Gear', 'None', '2 GP', '5', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>กระเป๋าสะพายหลัง สามารถบรรทุกน้ำหนักได้สูงสุด 30 ปอนด์ ในปริมาตร 1 ลูกบาศก์ฟุต นอกจากนี้ยังสามารถใช้เป็นกระเป๋าข้างอานสัตว์พาหนะ (Saddlebag) ได้ด้วย</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 96', 0, NULL, NULL),
('bag-of-holding', 'Bag of Holding', NULL, 'Magic Item', 'Wondrous Item', 'Uncommon', NULL, '5', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>ถุงนี้มีพื้นที่มิติด้านในกว้างขวางกว่ามิติภายนอกอย่างมาก สามารถบรรจุสิ่งของได้หนักสูงสุดถึง 500 ปอนด์ ในปริมาตรไม่เกิน 64 ลูกบาศก์ฟุต โดยตัวถุงจะมีน้ำหนักคงที่เพียง 5 ปอนด์เสมอไม่ว่าจะใส่ของไว้มากเท่าใด</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 212', 0, NULL, NULL),
('bagpipes', 'Bagpipes', NULL, 'Tool', 'Musical Instrument', 'None', '30 GP', '6 lb.', '', '', '', 'Ability: Charisma', '', '', '', '**ความสามารถ (Ability):** Charisma (ประเภทเครื่องดนตรี Musical Instrument)\n\n**การใช้งาน (Utilize):** บรรเลงบทเพลงที่รู้จัก (DC 10) หรือด้นสดแต่งทำนองใหม่ (DC 15)', '{\"logic\":{\"tool_type\":\"Musical Instrument\",\"ability\":\"Charisma\",\"utilize\":\"Play a known tune (DC 10), or improvise a song (DC 15)\"},\"display\":\"Ability: Charisma | Variant of Musical Instrument\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('bag_of_beans', 'Bag of Beans', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Rare_\n\nถุงผ้านี้บรรจุถั่วแห้ง 3d4 เมล็ด เมื่อนำเมล็ดถั่วไปฝังลงในดินและรดน้ำ จะเกิดผลลัพธ์เวทมนตร์อันน่าอัศจรรย์แบบสุ่มตามตาราง d100 เช่น มีต้นถั่วยักษ์โตขึ้นสู่สวรรค์, สัตว์ประหลาดปรากฏตัว, เกิดน้ำพุน้ำหวาน, หรือผลไม้วิเศษที่เพิ่มค่าความสามารถ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('bag_of_devouring', 'Bag of Devouring', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Very Rare_\n\nถุงนี้มีรูปลักษณ์ภายนอกเหมือน _Bag of Holding_ ทุกประการ แต่ความจริงแล้วมันคือช่องปากของสิ่งมีชีวิตข้ามมิติขนาดยักษ์ วัตถุที่ใส่เข้าไปจะถูกย่อยสลายหายไป และสิ่งมีชีวิตใดที่ยื่นตัวเข้าไปข้างในจะถูกลากเข้าไปและตกอยู่ในอันตรายถึงชีวิต', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('bag_of_tricks', 'Bag of Tricks', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon_\n\nถุงผ้าลึกลับที่ดูเหมือนว่างเปล่า แต่เมื่อคุณเอื้อมมือเข้าไปข้างในจะสัมผัสได้ถึงก้อนขนนุ่มๆ คุณสามารถใช้แอ็กชัน Magic ดึงก้อนขนออกมาแล้วขว้างไปในระยะ 20 ฟุต ก้อนขนจะกลายร่างเป็นสัตว์อสูรพันธมิตรแบบสุ่มตามสีของถุง (Gray, Rust หรือ Tan) สัตว์จะเชื่อฟังคำสั่งของคุณและคงอยู่จนกว่าจะตายหรือถึงยามรุ่งอรุณ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('ball_bearings', 'Ball Bearings', NULL, 'Gear', NULL, 'None', '1 GP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'คุณสามารถใช้แอ็กชัน Utilize เพื่อเทลูกปรายเหล็ก (Ball Bearings) จำนวน 1,000 ลูกออกจากถุง กระจายคลุมพื้นที่ราบเรียบขนาด 10x10 ฟุต สิ่งมีชีวิตที่ก้าวเข้าไปในพื้นที่นั้นต้องผ่านการทอยเซฟ DC 10 Dexterity มิฉะนั้นจะล้มลง (Prone)', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('barrel', 'Barrel', NULL, 'Gear', NULL, 'None', '2 GP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ถังไม้ใหญ่ บรรจุของเหลวได้สูงสุด 40 แกลลอน หรือบรรจุของแห้งได้สูงสุด 4 ลูกบาศก์ฟุต', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('basket', 'Basket', NULL, 'Gear', NULL, 'None', '4 SP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ตะกร้าสาน บรรทุกน้ำหนักได้สูงสุด 40 ปอนด์ ในปริมาตร 2 ลูกบาศก์ฟุต', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('battleaxe', 'Battleaxe', NULL, 'Weapon', 'Martial Melee', 'None', '10 GP', '4', NULL, '1d8 Slashing', 'Topple', 'Versatile (1d10)', NULL, NULL, NULL, 'อาวุธ Martial Melee สร้างความเสียหาย Slashing (ฟัน) 1d8 คุณสมบัติ: Versatile (1d10) ความชำนาญอาวุธ (Weapon Mastery): Topple น้ำหนัก: 4 ปอนด์, ราคา: 10 GP', '{\"logic\":{\"weapon_category\":\"Martial\",\"damage_dice\":\"1d8\",\"damage_type\":\"Slashing\",\"versatile_dice\":\"1d10\",\"properties\":[\"Versatile\"],\"mastery_id\":\"topple\"},\"display\":\"1d8 Slashing | Versatile (1d10) | Mastery: Topple\",\"modifiers\":[]}', 'SRD 5.2.1, Page 91', 0, NULL, NULL),
('bead_of_force', 'Bead of Force', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Rare_\n\nลูกปัดสีดำขนาดเล็ก คุณสามารถใช้แอ็กชัน Magic ขว้างลูกปัดไปได้ไกลสูงสุด 60 ฟุต เมื่อกระทบเป้าหมาย ลูกปัดจะระเบิดออกสร้างความเสียหาย Force 5d4 แก่สิ่งมีชีวิตในรัศมี 10 ฟุต และกักขังสิ่งมีชีวิตในพื้นที่ไว้ในทรงกลมโปร่งแสงที่ไม่อาจผ่านเข้าออกได้เป็นเวลา 1 นาที', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('bead_of_nourishment', 'Bead of Nourishment', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Common_\n\nลูกปัดเจลาตินไร้รสชาติ เมื่อวางบนลิ้นจะละลายทันที และมอบคุณค่าทางอาหารเทียบเท่ากับเสบียงอาหาร 1 วันเต็ม', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('bedroll', 'Bedroll', NULL, 'Gear', 'Adventuring Gear', 'None', '1 GP', '7', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>ถุงนอนสำหรับสิ่งมีชีวิตขนาด Small หรือ Medium หนึ่งตัว ขณะนอนในถุงนอน คุณจะผ่านการทอยเซฟต้านสภาพอากาศหนาวเย็นจัดโดยอัตโนมัติ</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 96', 0, NULL, NULL),
('bell', 'Bell', NULL, 'Gear', NULL, 'None', '1 GP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'เมื่อสั่นกระดิ่งโดยใช้แอ็กชัน Utilize กระดิ่งจะส่งเสียงดังที่สามารถได้ยินได้ในระยะไกลสูงสุดถึง 60 ฟุต', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('belt-of-giant-strength', 'Belt of Giant Strength', NULL, 'Magic Item', 'Wondrous Item', 'Varies', NULL, '0', 'Requires Attunement', NULL, NULL, NULL, NULL, NULL, NULL, '<p>ขณะสวมเข็มขัดนี้ ค่า Strength ของคุณจะเปลี่ยนเป็นค่าพลังที่เข็มขัดมอบให้ (ตั้งแต่ Hill Giant: 21 ไปจนถึง Storm Giant: 29) เข็มขัดจะไม่มีผลหากค่า Strength ตามปกติของคุณสูงกว่าค่าของเข็มขัดอยู่แล้ว</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 213', 0, NULL, NULL),
('belt_of_dwarvenkind', 'Belt of Dwarvenkind', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Rare (Requires Attunement)_\n\nขณะสวมเข็มขัดนี้ คุณจะได้รับประโยชน์ดังต่อไปนี้:\n- **Dwarvish:** คุณสามารถพูด อ่าน และเขียนภาษาคนแคระ (Dwarvish) ได้\n- **Friend of Dwarves:** คุณมี Advantage ในการทอย Charisma (Persuasion) check เมื่อปฏิสัมพันธ์กับคนแคระ\n- **Dwarven Resilience:** ค่า Constitution ของคุณเพิ่มขึ้น +2 (สูงสุด 20), คุณมี Advantage ในการทอยเซฟต้านพิษ และมีความต้านทานต่อความเสียหาย Poison\n- **Darkvision:** คุณมี Darkvision ในระยะ 60 ฟุต\n- มีโอกาส 50% ทุกเช้าที่หนวดเคราหนาดกจะงอกยาวขึ้นบนใบหน้าของคุณ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('berserker_axe', 'Berserker Axe', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Weapon (Battleaxe, Greataxe, or Halberd), Rare (Requires Attunement)_\n\nคุณจะได้รับโบนัส +1 ในการทอยโจมตีและทอยความเสียหายด้วยอาวุธเวทมนตร์นี้ และค่า HP สูงสุดของคุณจะเพิ่มขึ้นเท่ากับเลเวลของคุณ\n\n**คำสาป (Curse):** อาวุธนี้ติดคำสาปบ้าคลั่ง เมื่อคุณได้รับความเสียหายขณะถืออาวุธนี้ คุณต้องผ่านการทอยเซฟ DC 15 Wisdom มิฉะนั้นจะตกอยู่ในสภาวะคลั่ง (Berserk) โจมตีสิ่งมีชีวิตที่อยู่ใกล้ที่สุดไม่ว่าจะเป็นมิตรหรือศัตรูจนกว่าจะไม่มีสิ่งมีชีวิตใดอยู่ในระยะ 60 ฟุต', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('blanket', 'Blanket', NULL, 'Gear', NULL, 'None', '5 SP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'เมื่อห่มผ้าห่มนี้ คุณจะได้รับ Advantage ในการทอยเซฟต้านความหนาวเย็นจัด (Extreme Cold)', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('block_and_tackle', 'Block and Tackle', NULL, 'Gear', NULL, 'None', '1 GP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ชุดรอกผ่อนแรง ช่วยให้คุณสามารถยกหรือชักลากน้ำหนักได้สูงสุดถึงสี่เท่าของน้ำหนักปกติที่คุณสามารถยกได้', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('blowgun', 'Blowgun', NULL, 'Weapon', 'Martial Ranged', 'None', '10 GP', '1', NULL, '1 Piercing', 'Vex', 'Ammunition (Range 25/100; Needle), Loading', NULL, NULL, NULL, 'อาวุธ Martial Ranged สร้างความเสียหาย Piercing (แทง) 1 คุณสมบัติ: Ammunition (กระสุน ระยะ 25/100 ฟุต; ดอกเข็ม Needle), Loading (บรรจุกระสุน) ความชำนาญอาวุธ (Weapon Mastery): Vex น้ำหนัก: 1 ปอนด์, ราคา: 10 GP', '{\"logic\":{\"weapon_category\":\"Martial\",\"damage_dice\":\"1\",\"damage_type\":\"Piercing\",\"range\":{\"normal\":25,\"long\":100},\"properties\":[\"Ammunition\",\"Loading\"],\"mastery_id\":\"vex\"},\"display\":\"1 Piercing | Ammunition (Range 25\\/100; Needle), Loading | Mastery: Vex\",\"modifiers\":[]}', 'SRD 5.2.1, Page 91', 0, NULL, NULL),
('book', 'Book', NULL, 'Gear', NULL, 'None', '25 GP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'หนังสือบันทึกหรือตำรา หากคุณเปิดค้นคว้าจากหนังสือที่ไม่ใช่นิยายที่มีเนื้อหาตรงกับหัวข้อนั้นๆ คุณจะได้รับ Advantage ในการทอยเช็ก Intelligence ที่เกี่ยวข้องกับหัวข้อดังกล่าว', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('boots-of-elvenkind', 'Boots of Elvenkind', NULL, 'Magic Item', 'Wondrous Item', 'Uncommon', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>ขณะสวมรองเท้าบูทคู่นี้ ฝีเท้าของคุณจะไม่ส่งเสียงดังใดๆ และคุณจะได้รับ Advantage ในการทอย Dexterity (Stealth) check ที่ต้องอาศัยความเงียบ</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 213', 0, NULL, NULL),
('boots_of_levitation', 'Boots of Levitation', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Rare (Requires Attunement)_\n\nขณะสวมรองเท้าคู่นี้ คุณสามารถร่ายคาถา _Levitate_ ใส่ตัวเองได้ตามต้องการโดยไม่ต้องใช้ Spell Slot หรือชิ้นส่วนวัตถุดิบ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('boots_of_speed', 'Boots of Speed', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Rare (Requires Attunement)_\n\nขณะสวมรองเท้าคู่นี้ คุณสามารถใช้โบนัสแอ็กชันเคาะส้นเท้าเข้าด้วยกัน เมื่อทำเช่นนั้น ความเร็วในการเดินของคุณจะเพิ่มขึ้นเป็นสองเท่า และการโจมตีฉวยโอกาส (Opportunity Attacks) ที่กระทำต่อคุณจะติด Disadvantage ผลลัพธ์นี้คงอยู่นานสูงสุด 10 นาที (สามารถแบ่งใช้ได้) และจะฟื้นฟูการใช้งานใหม่หลัง Long Rest', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('boots_of_striding_and_springing', 'Boots of Striding and Springing', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon (Requires Attunement)_\n\nขณะสวมรองเท้าคู่นี้ ความเร็วในการเดินของคุณจะกลายเป็น 30 ฟุต (หากเดิมต่ำกว่านั้น) และความเร็วของคุณจะไม่ลดลงจากการบรรทุกน้ำหนักเกินหรือสวมเกราะหนัก นอกจากนี้คุณยังสามารถกระโดดได้ไกลกว่าปกติถึง 3 เท่า', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('boots_of_the_winterlands', 'Boots of the Winterlands', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon (Requires Attunement)_\n\nรองเท้าบุขนสัตว์ที่มอบความอบอุ่นแก่ผู้สวมใส่:\n- คุณมีความต้านทานต่อความเสียหาย Cold\n- คุณไม่ได้รับผลกระทบจากสภาพอากาศหนาวจัดจนถึงอุณหภูมิต่ำกว่าศูนย์\n- คุณสามารถเดินบนน้ำแข็งหรือหิมะหนาได้โดยไม่ถือเป็นพื้นที่ยากลำบาก (Difficult Terrain)', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('bottle_glass', 'Bottle, Glass', NULL, 'Gear', NULL, 'None', '2 GP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ขวดแก้ว บรรจุของเหลวได้สูงสุด 1.5 ไพนต์ (ประมาณ 0.7 ลิตร)', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('bowl_of_commanding_water_elementals', 'Bowl of Commanding Water Elementals', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Rare_\n\nขณะที่อ่างนี้เต็มไปด้วยน้ำ คุณสามารถใช้แอ็กชัน Magic เพื่ออัญเชิญ Water Elemental ออกมาจากน้ำได้ ธาตุแห่งน้ำจะเชื่อฟังคำสั่งของคุณเป็นเวลา 1 ชั่วโมง สามารถใช้งานได้วันละหนึ่งครั้งเมื่อถึงยามรุ่งอรุณถัดไป', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('bracers-of-defense', 'Bracers of Defense', NULL, 'Magic Item', 'Wondrous Item', 'Rare', NULL, '0', 'Requires Attunement', NULL, NULL, NULL, NULL, NULL, NULL, '<p>ขณะสวมสนับแขนคู่นี้ คุณจะได้รับโบนัส +2 ใน Armor Class หากคุณไม่ได้สวมชุดเกราะใดๆ และไม่ได้ถือโล่</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 214', 0, NULL, NULL),
('bracers_of_archery', 'Bracers of Archery', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon (Requires Attunement)_\n\nขณะสวมสนับแขนคู่นี้ คุณจะมีความชำนาญในการใช้ Longbow และ Shortbow และคุณจะได้รับโบนัส +2 ในการทอยความเสียหายจากการโจมตีระยะไกลด้วยธนูทั้งสองชนิดนี้', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('brazier_of_commanding_fire_elementals', 'Brazier of Commanding Fire Elementals', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Rare_\n\nขณะยืนอยู่ใกล้เตาไฟนี้ คุณสามารถใช้แอ็กชัน Magic เพื่ออัญเชิญ Fire Elemental ออกมาจากเปลวไฟได้ ธาตุแห่งไฟจะเชื่อฟังคำสั่งของคุณเป็นเวลา 1 ชั่วโมง สามารถใช้งานได้วันละหนึ่งครั้งเมื่อถึงยามรุ่งอรุณถัดไป', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('breastplate', 'Breastplate', NULL, 'Armor', 'Medium Armor', 'None', '400 GP', '20', NULL, NULL, NULL, NULL, '14 + Dex modifier (max 2)', NULL, NULL, 'AC พื้นฐาน: 14 + ตัวปรับแต่ง Dex (สูงสุด 2), ค่า Strength ที่ต้องการ: —, การพรางตัว (Stealth): ปกติ, น้ำหนัก: 20 ปอนด์, ราคา: 400 GP', '{\"logic\":{\"armor_category\":\"Medium\",\"base_ac\":14,\"dex_modifier\":\"max2\",\"stealth_disadvantage\":false,\"strength_requirement\":0},\"display\":\"AC: 14 + Dex modifier (max 2) | Medium Armor\",\"modifiers\":[]}', 'SRD 5.2.1, Page 92', 0, NULL, NULL),
('brewers-supplies', 'Brewer\'s Supplies', NULL, 'Tool', 'Artisan\'s Tools', 'None', '20 GP', '9', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p><b>ความสามารถ (Ability):</b> Intelligence<br><b>การใช้งาน (Utilize):</b> ตรวจจับเครื่องดื่มที่มีพิษ (DC 15) หรือระบุประเภทสุรา (DC 10)<br><b>การสร้าง (Craft):</b> เครื่องดื่มแอลกอฮอล์ (Ale, Wine)</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 93', 0, NULL, NULL),
('brewers_supplies', 'Brewer\'s Supplies', NULL, 'Tool', 'Tool', 'None', '20 GP', '9 lb.', '', '', '', 'Ability: Intelligence', '', '', '', '**ความสามารถ (Ability):** Intelligence\n\n**การใช้งาน (Utilize):** ตรวจจับเครื่องดื่มที่มีพิษ (DC 15) หรือระบุประเภทสุรา (DC 10)\n\n**การสร้าง (Craft):** เครื่องดื่มแอลกอฮอล์ (Ale, Wine)', '{\"logic\":{\"tool_type\":\"Tool\",\"ability\":\"Intelligence\",\"utilize\":\"Detect poisoned drink (DC 15), or identify alcohol (DC 10)\",\"craft\":\"Antitoxin\"},\"display\":\"Ability: Intelligence | Craft: Antitoxin\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('brooch_of_shielding', 'Brooch of Shielding', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon (Requires Attunement)_\n\nขณะกลัดเข็มกลัดนี้ คุณจะมีความต้านทาน (Resistance) ต่อความเสียหาย Force และคุณมีภูมิคุ้มกัน (Immunity) สมบูรณ์ต่อความเสียหายจากคาถา _Magic Missile_', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('broom-of-flying', 'Broom of Flying', NULL, 'Magic Item', 'Wondrous Item', 'Uncommon', NULL, '3', 'Requires Attunement', NULL, NULL, NULL, NULL, NULL, NULL, '<p>ไม้กวาดไม้นี้ทำงานเหมือนไม้กวาดทั่วไป จนกระทั่งคุณขึ้นคร่อมและใช้แอ็กชัน Magic สั่งให้มันลอย ไม้กวาดมีความเร็วในการบิน (Fly Speed) 50 ฟุต และสามารถบรรทุกน้ำหนักได้สูงสุด 400 ปอนด์ (หากบรรทุกเกิน 200 ปอนด์ ความเร็วจะลดลงเหลือ 30 ฟุต)</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 214', 0, NULL, NULL),
('bucket', 'Bucket', NULL, 'Gear', NULL, 'None', '5 CP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ถังน้ำ บรรจุของเหลวหรือสิ่งของได้สูงสุดครึ่งลูกบาศก์ฟุต (ประมาณ 3 แกลลอน)', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('burglars-pack', 'Burglar\'s Pack', NULL, 'Pack', 'Equipment Pack', 'None', '16 GP', '42', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>ประกอบด้วย: กระเป๋าสะพาย (Backpack), ลูกปรายเหล็ก 1,000 ลูก (Ball Bearings), กระดิ่ง (Bell), เทียน 10 เล่ม (Candles), ชะแลง (Crowbar), ตะเกียงคลุมโคม (Hooded Lantern), น้ำมัน 7 ขวด (Oil), เสบียงอาหาร 5 วัน (Rations), เชือกป่าน 50 ฟุต (Rope), ชุดจุดไฟ (Tinderbox) และถุงใส่น้ำ (Waterskin)</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 96', 0, NULL, NULL),
('calligraphers-supplies', 'Calligrapher\'s Supplies', NULL, 'Tool', 'Artisan\'s Tools', 'None', '10 GP', '5', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p><b>ความสามารถ (Ability):</b> Dexterity<br><b>การใช้งาน (Utilize):</b> เขียนตัวอักษรวิจิตรตระการตาที่ยากต่อการปลอมแปลง (DC 15)<br><b>การสร้าง (Craft):</b> Ink, Spell Scroll</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 93', 0, NULL, NULL),
('calligraphers_supplies', 'Calligrapher\'s Supplies', NULL, 'Tool', 'Tool', 'None', '10 GP', '5 lb.', '', '', '', 'Ability: Dexterity', '', '', '', '**ความสามารถ (Ability):** Dexterity\n\n**การใช้งาน (Utilize):** เขียนตัวอักษรวิจิตรตระการตาที่ยากต่อการปลอมแปลง (DC 15)\n\n**การสร้าง (Craft):** Ink, Spell Scroll', '{\"logic\":{\"tool_type\":\"Tool\",\"ability\":\"Dexterity\",\"utilize\":\"Write text with impressive flourishes that guard against forgery (DC 15)\",\"craft\":\"Ink, _Spell Scroll_\"},\"display\":\"Ability: Dexterity | Craft: Ink, _Spell Scroll_\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('caltrops', 'Caltrops', NULL, 'Gear', NULL, 'None', '1 GP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'คุณสามารถใช้แอ็กชัน Utilize เพื่อโปรยกับดักหนามเท้า (Caltrops) จากถุงลงบนพื้นที่ขนาด 5x5 ฟุต สิ่งมีชีวิตใดที่เดินเข้าไปในพื้นที่ต้องผ่านการทอยเซฟ DC 15 Dexterity มิฉะนั้นจะหยุดเคลื่อนที่ทันทีและได้รับความเสียหาย Piercing 1 หน่วย พร้อมลดความเร็วในการเดินลง 10 ฟุตจนกว่าจะได้รับการรักษา', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('camel', 'Camel', NULL, 'Mount', 'Mount', 'None', '50 GP', '0', NULL, NULL, NULL, 'Carrying Capacity: 450 lb.', NULL, NULL, NULL, 'ความจุในการบรรทุก (Carrying Capacity): 450 ปอนด์ ความเร็ว (Speed): 50 ฟุต', '{\"logic\":{\"carrying_capacity\":\"450 lb.\"},\"display\":\"Carrying Capacity: 450 lb.\",\"modifiers\":[]}', 'SRD 5.2.1, Page 100', 0, NULL, NULL),
('candle', 'Candle', NULL, 'Gear', NULL, 'None', '1 CP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'เมื่อจุดเทียน เทียนจะส่องสว่างระดับ Bright Light ในรัศมี 5 ฟุต และ Dim Light ออกไปอีก 5 ฟุต เป็นระยะเวลา 1 ชั่วโมง', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('candle_of_invocation', 'Candle of Invocation', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Very Rare (Requires Attunement)_\n\nเทียนเล่มนี้เชื่อมโยงกับแนวศีลธรรม (Alignment) หนึ่ง เมื่อจุดไฟขึ้นมา มันจะเปล่งแสงในรัศมี 30 ฟุต สิ่งมีชีวิตในรัศมีที่มี Alignment ตรงกับเทียนจะได้รับ Advantage ในการทอยโจมตี ทอยเซฟ และ Ability check นักบวชหรือผู้ใช้เวทที่มี Alignment ตรงกันสามารถร่ายคาถาระดับเลเวล 1 ได้โดยไม่ต้องเสีย Spell Slot เทียนสามารถเผาไหม้ได้นานสูงสุด 4 ชั่วโมง', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('cape_of_the_mountebank', 'Cape of the Mountebank', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Rare_\n\nผ้าคลุมที่มีกลิ่นกำมะถันจางๆ ขณะสวมใส่ คุณสามารถใช้แอ็กชัน Magic เพื่อร่ายคาถา _Dimension Door_ พร้อมปล่อยกลุ่มควันหนาทึบออกมาในจุดที่คุณจากไปและจุดที่คุณปรากฏตัวขึ้น สามารถใช้งานได้วันละหนึ่งครั้งเมื่อถึงยามรุ่งอรุณถัดไป', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('carpenters-tools', 'Carpenter\'s Tools', NULL, 'Tool', 'Artisan\'s Tools', 'None', '8 GP', '6', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p><b>ความสามารถ (Ability):</b> Strength<br><b>การใช้งาน (Utilize):</b> ตอกปิดผนึกหรือแงะเปิดประตูหรือภาชนะ (DC 20)<br><b>การสร้าง (Craft):</b> Club, Greatclub, Quarterstaff, Barrel, Chest, Ladder, Pole, Portable Ram, Torch</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 93', 0, NULL, NULL),
('carpenters_tools', 'Carpenter\'s Tools', NULL, 'Tool', 'Tool', 'None', '8 GP', '6 lb.', '', '', '', 'Ability: Strength', '', '', '', '**ความสามารถ (Ability):** Strength\n\n**การใช้งาน (Utilize):** ตอกปิดผนึกหรือแงะเปิดประตูหรือภาชนะ (DC 20)\n\n**การสร้าง (Craft):** Club, Greatclub, Quarterstaff, Barrel, Chest, Ladder, Pole, Portable Ram, Torch', '{\"logic\":{\"tool_type\":\"Tool\",\"ability\":\"Strength\",\"utilize\":\"Seal or pry open a door or container (DC 20)\",\"craft\":\"Club, Greatclub, Quarterstaff, Barrel, Chest, Ladder, Pole, Portable Ram, Torch\"},\"display\":\"Ability: Strength | Craft: Club, Greatclub, Quarterstaff, Barrel, Chest, Ladder, Pole, Portable Ram, Torch\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('carpet_of_flying', 'Carpet of Flying', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Very Rare_\n\nพรมวิเศษที่สามารถลอยตัวและบินไปในอากาศได้ตามคำสั่ง โดยความเร็วในการบินและความจุน้ำหนักจะขึ้นอยู่กับขนาดของพรม (ตั้งแต่ขนาด 3x5 ฟุต บินเร็ว 80 ฟุต รับน้ำหนัก 200 ปอนด์ ไปจนถึงขนาด 6x9 ฟุต บินเร็ว 30 ฟุต รับน้ำหนัก 800 ปอนด์)', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('carriage', 'Carriage', NULL, 'Vehicle', 'Land Vehicle / Harness', 'None', '100 GP', '600 lb.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ยานพาหนะทางบกหรืออุปกรณ์เครื่องเทียมสัตว์พาหนะสำหรับลากจูง', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 100', 0, NULL, NULL),
('cart', 'Cart', NULL, 'Vehicle', 'Land Vehicle / Harness', 'None', '15 GP', '200 lb.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ยานพาหนะล้อลากทางบกสองล้อสำหรับบรรทุกสัมภาระ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 100', 0, NULL, NULL),
('cartographers_tools', 'Cartographer\'s Tools', NULL, 'Tool', 'Tool', 'None', '15 GP', '6 lb.', '', '', '', 'Ability: Wisdom', '', '', '', '**ความสามารถ (Ability):** Wisdom\n\n**การใช้งาน (Utilize):** ร่างแผนที่พื้นที่ขนาดเล็ก (DC 15)\n\n**การสร้าง (Craft):** Map', '{\"logic\":{\"tool_type\":\"Tool\",\"ability\":\"Wisdom\",\"utilize\":\"Draft a map of a small area (DC 15)\",\"craft\":\"Map\"},\"display\":\"Ability: Wisdom | Craft: Map\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('case_crossbow_bolt', 'Case, Crossbow Bolt', NULL, 'Gear', NULL, 'None', '1 GP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'กระบอกใส่ดอกหน้าไม้ สามารถบรรจุดอกหน้าไม้ (Bolts) ได้สูงสุด 20 ดอก', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('case_map_or_scroll', 'Case, Map or Scroll', NULL, 'Gear', NULL, 'None', '1 GP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'กระบอกใส่แผนที่หรือม้วนคัมภีร์ สามารถบรรจุกระดาษได้สูงสุด 10 แผ่น หรือกระดาษหนัง 5 แผ่น และช่วยป้องกันน้ำซึมเข้า', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('censer_of_controlling_air_elementals', 'Censer of Controlling Air Elementals', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Rare_\n\nขณะแกว่งกระถางกำยานนี้พร้อมจุดเครื่องหอม คุณสามารถใช้แอ็กชัน Magic เพื่ออัญเชิญ Air Elemental ออกมา ธาตุแห่งลมจะเชื่อฟังคำสั่งของคุณเป็นเวลา 1 ชั่วโมง สามารถใช้งานได้วันละหนึ่งครั้งเมื่อถึงยามรุ่งอรุณถัดไป', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('chain', 'Chain', NULL, 'Gear', NULL, 'None', '5 GP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'คุณสามารถใช้แอ็กชัน Utilize เพื่อพันโซ่ล่ามสิ่งมีชีวิตที่ไม่ยินยอมในระยะ 5 ฟุตที่มีขนาดไม่เกินตัวคุณ โดยต้องชนะการแข่งทอย Strength (Athletics) โซ่มีค่า AC 19 และมี HP 10 (การทำลายต้องผ่าน DC 20 Strength check)', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('chain-mail', 'Chain Mail', NULL, 'Armor', 'Heavy Armor', 'None', '75 GP', '55', NULL, NULL, NULL, NULL, '16', 'Str 13', 'Disadvantage', 'AC พื้นฐาน: 16, ค่า Strength ที่ต้องการ: Str 13, การพรางตัว (Stealth): Disadvantage (เสียเปรียบ), น้ำหนัก: 55 ปอนด์, ราคา: 75 GP', '{\"logic\":{\"armor_category\":\"Heavy\",\"base_ac\":16,\"dex_modifier\":\"none\",\"stealth_disadvantage\":true,\"strength_requirement\":13},\"display\":\"AC: 16 | Heavy Armor\",\"modifiers\":[]}', 'SRD 5.2.1, Page 92', 0, NULL, NULL),
('chain-shirt', 'Chain Shirt', NULL, 'Armor', 'Medium Armor', 'None', '50 GP', '20', NULL, NULL, NULL, NULL, '13 + Dex modifier (max 2)', NULL, NULL, 'AC พื้นฐาน: 13 + ตัวปรับแต่ง Dex (สูงสุด 2), ค่า Strength ที่ต้องการ: —, การพรางตัว (Stealth): ปกติ, น้ำหนัก: 20 ปอนด์, ราคา: 50 GP', '{\"logic\":{\"armor_category\":\"Medium\",\"base_ac\":13,\"dex_modifier\":\"max2\",\"stealth_disadvantage\":false,\"strength_requirement\":0},\"display\":\"AC: 13 + Dex modifier (max 2) | Medium Armor\",\"modifiers\":[]}', 'SRD 5.2.1, Page 92', 0, NULL, NULL),
('charges', 'Charges', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ไอเทมเวทมนตร์บางชิ้นมีหน่วยชาร์จ (Charges) ที่ต้องใช้เพื่อเปิดใช้งานคุณสมบัติพิเศษ จำนวนชาร์จที่เหลืออยู่จะแสดงให้ทราบเมื่อร่ายคาถา _Identify_ หรือเมื่อผูกพัน (Attunement) กับไอเทมนั้น โดยทั่วไปไอเทมจะฟื้นฟูชาร์จตามจำนวนที่กำหนดในยามรุ่งอรุณของแต่ละวัน', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('chariot', 'Chariot', NULL, 'Vehicle', 'Land Vehicle / Harness', 'None', '250 GP', '100 lb.', '', '', '', '', '', '', '', 'ราชรถหรือเกวียนรบสองล้อเทียมสัตว์พาหนะ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('chest', 'Chest', NULL, 'Gear', NULL, 'None', '5 GP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'หีบไม้ บรรจุสิ่งของได้สูงสุด 12 ลูกบาศก์ฟุต หรือน้ำหนักประมาณ 300 ปอนด์', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('chime_of_opening', 'Chime of Opening', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Rare_\n\nกระดิ่งท่อโลหะกลวงยาวประมาณ 1 ฟุต คุณสามารถใช้แอ็กชัน Magic เคาะกระดิ่งเล็งไปที่ประตู บานพับ หีบ หรือแม่กุญแจในระยะ 120 ฟุตเพื่อปลดล็อกหรือปลดสลักออกโดยอัตโนมัติ กระดิ่งนี้ใช้งานได้ทั้งหมด 10 ครั้ง และจะแตกร้าวไร้พลังเมื่อใช้ครบ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('circlet_of_blasting', 'Circlet of Blasting', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon_\n\nขณะสวมรัดเกล้านี้ คุณสามารถร่ายคาถา _Scorching Ray_ (+5 ในการทอยโจมตี) ได้หนึ่งครั้ง รัดเกล้าจะฟื้นฟูพลังนี้ใหม่ในยามรุ่งอรุณถัดไป', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('climber_s_kit', 'Climber\'s Kit', NULL, 'Gear', NULL, 'None', '25 GP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ชุดอุปกรณ์ปีนเขา ประกอบด้วยเดือยรองเท้า, ถุงมือปีน, ลิ่มตอกหิน และสายรัดตัว คุณสามารถใช้แอ็กชัน Utilize เพื่อผูกยึดตัวเองเข้ากับหน้าผา ทำให้คุณไม่สามารถตกเกินกว่า 25 ฟุตจากจุดที่ยึดไว้', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('cloak-of-displacement', 'Cloak of Displacement', NULL, 'Magic Item', 'Wondrous Item', 'Rare', NULL, '0', 'Requires Attunement', NULL, NULL, NULL, NULL, NULL, NULL, '<p>ขณะสวมผ้าคลุมนี้ ผ้าคลุมจะฉายภาพลวงตาทำให้ดูเหมือนว่าคุณยืนอยู่ห่างจากตำแหน่งจริงเล็กน้อย ส่งผลให้การทอยโจมตีทั้งหมดที่กระทำต่อคุณติด Disadvantage หากคุณได้รับความเสียหาย คุณสมบัตินี้จะหยุดทำงานชั่วคราวจนกว่าจะเริ่มเทิร์นถัดไปของคุณ</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 215', 0, NULL, NULL),
('cloak-of-elvenkind', 'Cloak of Elvenkind', NULL, 'Magic Item', 'Wondrous Item', 'Uncommon', NULL, '0', 'Requires Attunement', NULL, NULL, NULL, NULL, NULL, NULL, '<p>ขณะสวมผ้าคลุมนี้ การทอย Wisdom (Perception) ใดๆ เพื่อสังเกตเห็นคุณจะติด Disadvantage และคุณจะได้รับ Advantage ในการทอย Dexterity (Stealth) check เพื่อหลบซ่อนตัว</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 215', 0, NULL, NULL),
('cloak-of-protection', 'Cloak of Protection', NULL, 'Magic Item', 'Wondrous Item', 'Uncommon', NULL, '0', 'Requires Attunement', NULL, NULL, NULL, NULL, NULL, NULL, '<p>คุณจะได้รับโบนัส +1 ใน Armor Class และการทอยเซฟ (Saving Throws) ทุกประเภทขณะสวมผ้าคลุมนี้</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 216', 0, NULL, NULL),
('cloak_of_arachnida', 'Cloak of Arachnida', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Very Rare (Requires Attunement)_\n\nผ้าคลุมทอจากไหมสีดำแทรกด้วยด้ายเงิน มอบความสามารถแห่งแมงมุม:\n- คุณมีความต้านทานต่อความเสียหาย Poison\n- คุณมีความเร็วในการปีนป่ายเท่ากับความเร็วในการเดิน และสามารถเดินบนใยแมงมุมหรือเพดานได้โดยไม่ลื่นหล่น (Spider Climb)\n- คุณไม่ติดใยแมงมุมและเดินผ่านใยแมงมุมได้ตามปกติ\n- คุณสามารถร่ายคาถา _Web_ (DC 13) ได้วันละหนึ่งครั้ง', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('cloak_of_invisibility', 'Cloak of Invisibility', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Legendary (Requires Attunement)_\n\nผ้าคลุมล่องหน มีชาร์จ 3 ชาร์จ (ฟื้นฟู 1d3 ชาร์จทุกเช้า) ขณะสวมผ้าคลุม คุณสามารถดึงฮู้ดขึ้นมาคลุมศีรษะเป็นแอ็กชัน Magic เพื่อล่องหนหายตัวไปอย่างสมบูรณ์ (Invisible) รวมถึงสิ่งของทั้งหมดที่คุณสวมใส่หรือถืออยู่', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('cloak_of_the_bat', 'Cloak of the Bat', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Rare (Requires Attunement)_\n\nขณะสวมผ้าคลุมนี้ คุณมี Advantage ในการทอย Dexterity (Stealth) check ในที่แสงสลัวหรือมืดสนิท คุณสามารถจับชายผ้าคลุมแล้วบินได้ด้วยความเร็ว 40 ฟุต หรือแปลงร่างเป็นค้างคาว (Bat) ได้ตามต้องการดั่งคาถา _Polymorph_', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('cloak_of_the_manta_ray', 'Cloak of the Manta Ray', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon (Requires Attunement)_\n\nขณะสวมผ้าคลุมนี้และดึงฮู้ดขึ้นคลุมศีรษะ คุณสามารถหายใจใต้น้ำได้ และมีความเร็วในการว่ายน้ำ (Swim Speed) 60 ฟุต', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('clothes_fine', 'Clothes, Fine', NULL, 'Gear', NULL, 'None', '15 GP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ชุดเสื้อผ้าหรูหรา ตัดเย็บจากผ้าเนื้อดีราคาแพงและประดับตกแต่งด้วยฝีมือประณีต สถานที่หรูหราบางแห่งหรือการเข้าพบชนชั้นสูงอาจอนุญาตให้เฉพาะผู้ที่สวมชุดนี้เข้าพบ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('clothes_traveler_s', 'Clothes, Traveler\'s', NULL, 'Gear', NULL, 'None', '2 GP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ชุดเสื้อผ้านักเดินทาง เสื้อผ้าที่ทนทานและออกแบบมาสำหรับการเดินทางไกลในสภาพแวดล้อมที่หลากหลาย', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('club', 'Club', NULL, 'Weapon', 'Simple Melee', 'None', '1 SP', '2', NULL, '1d4 Bludgeoning', 'Slow', 'Light', NULL, NULL, NULL, 'อาวุธ Simple Melee สร้างความเสียหาย Bludgeoning (ทุบ) 1d4 คุณสมบัติ: Light (เบา) ความชำนาญอาวุธ (Weapon Mastery): Slow น้ำหนัก: 2 ปอนด์, ราคา: 1 SP', '{\"logic\":{\"weapon_category\":\"Simple\",\"damage_dice\":\"1d4\",\"damage_type\":\"Bludgeoning\",\"properties\":[\"Light\"],\"mastery_id\":\"slow\"},\"display\":\"1d4 Bludgeoning | Light | Mastery: Slow\",\"modifiers\":[]}', 'SRD 5.2.1, Page 91', 0, NULL, NULL),
('cobblers_tools', 'Cobbler\'s Tools', NULL, 'Tool', 'Tool', 'None', '5 GP', '5 lb.', '', '', '', 'Ability: Dexterity', '', '', '', '**ความสามารถ (Ability):** Dexterity\n\n**การใช้งาน (Utilize):** ดัดแปลงรองเท้าเพื่อให้ผู้สวมใส่ได้เปรียบ (Advantage) ในการทอย Dexterity (Acrobatics) ครั้งถัดไป (DC 10)\n\n**การสร้าง (Craft):** Climber\'s Kit', '{\"logic\":{\"tool_type\":\"Tool\",\"ability\":\"Dexterity\",\"utilize\":\"Modify footwear to give Advantage on the wearer\'s next Dexterity (Acrobatics) check (DC 10)\",\"craft\":\"Climber\'s Kit\"},\"display\":\"Ability: Dexterity | Craft: Climber\'s Kit\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('component_pouch', 'Component Pouch', NULL, 'Gear', NULL, 'None', '25 GP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'กระเป๋าบรรจุวัตถุดิบร่ายเวทมนตร์ กันน้ำและมีช่องแบ่งมากมายสำหรับบรรจุ Material components ทั้งหมดที่ไม่มีราคาระบุไว้สำหรับการร่ายเวทมนตร์', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('conflict', 'Conflict', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'เมื่อผู้ครอบครองไอเทมเวทมนตร์ที่มีจิตวิญญาณและความรู้สึก (Sentient Magic Item) กระทำการที่ขัดแย้งกับเจตจำนงหรือศีลธรรมของไอเทม ความขัดแย้งอาจปะทุขึ้น ผู้ถือครองต้องทอยเซฟเพื่อต่อต้านการครอบงำทางจิตใจ มิฉะนั้นไอเทมจะเข้าควบคุมการกระทำของผู้ถือครองเป็นเวลาสั้นๆ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('cooks_utensils', 'Cook\'s Utensils', NULL, 'Tool', 'Tool', 'None', '1 GP', '8 lb.', '', '', '', 'Ability: Wisdom', '', '', '', '**ความสามารถ (Ability):** Wisdom\n\n**การใช้งาน (Utilize):** ปรุงแต่งรสชาติอาหารให้อร่อยยิ่งขึ้น (DC 10) หรือตรวจจับอาหารที่เน่าเสียหรือมียาพิษ (DC 15)\n\n**การสร้าง (Craft):** เสบียงอาหาร (Rations)', '{\"logic\":{\"tool_type\":\"Tool\",\"ability\":\"Wisdom\",\"utilize\":\"Improve food\'s flavor (DC 10), or detect spoiled or poisoned food (DC 15)\",\"craft\":\"Rations\"},\"display\":\"Ability: Wisdom | Craft: Rations\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('costume', 'Costume', NULL, 'Gear', NULL, 'None', '5 GP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ขณะสวมชุดคอสตูมปลอมตัว คุณจะได้รับ Advantage ในการทอยเช็กค่าความสามารถเพื่อสวมรอยเป็นบุคคลหรืออาชีพที่ชุดนั้นเป็นตัวแทน', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('crew', 'Crew', NULL, 'Gear', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'เรือที่มีขนาดใหญ่กว่าเรือ Keelboat หรือ Rowboat จำเป็นต้องมีลูกเรือที่มีความชำนาญ (Skilled hirelings) ในการควบคุมและดูแลรักษาเรือตามจำนวนที่กำหนดในตารางยานพาหนะ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('crowbar', 'Crowbar', NULL, 'Gear', 'Adventuring Gear', 'None', '2 GP', '5', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>การใช้ชะแลงช่วยให้คุณได้รับ Advantage ในการทอย Strength check ในสถานการณ์ที่สามารถนำชะแลงมาเป็นคานงัดผ่อนแรงได้</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 97', 0, NULL, NULL),
('crystal_ball', 'Crystal Ball', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Very Rare (Requires Attunement)_\n\nขณะสัมผัสลูกแก้วคริสตัลนี้ คุณสามารถใช้ร่ายคาถา _Scrying_ (Save DC 17) ได้ตามต้องการ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('crystal_ball_of_mind_reading', 'Crystal Ball of Mind Reading', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Legendary (Requires Attunement)_\n\nขณะสัมผัสลูกแก้วคริสตัลนี้ คุณสามารถร่ายคาถา _Scrying_ (Save DC 17) ได้ และในขณะที่สอดแนมเป้าหมายอยู่ คุณสามารถร่ายคาถา _Detect Thoughts_ (Save DC 17) ใสเป้าหมายผ่านลูกแก้วได้โดยไม่ต้องใช้ชิ้นส่วนวัตถุดิบ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL);
INSERT INTO `items` (`item_id`, `item_name`, `image_url`, `item_type`, `subcategory`, `rarity`, `cost`, `weight`, `attunement`, `damage`, `mastery`, `properties`, `ac`, `strength_req`, `stealth`, `item_desc`, `mechanics`, `srd_source`, `is_homebrew`, `author_id`, `deleted_at`) VALUES
('crystal_ball_of_telepathy', 'Crystal Ball of Telepathy', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Legendary (Requires Attunement)_\n\nขณะสัมผัสลูกแก้วคริสตัลนี้ คุณสามารถร่ายคาถา _Scrying_ (Save DC 17) ได้ และคุณสามารถสื่อสารทางจิต (Telepathy) กับสิ่งมีชีวิตในระยะ 30 ฟุตจากเซนเซอร์สอดแนม และร่ายคาถา _Suggestion_ (Save DC 17) ผ่านเซนเซอร์ได้วันละหนึ่งครั้ง', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('crystal_ball_of_true_seeing', 'Crystal Ball of True Seeing', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Legendary (Requires Attunement)_\n\nขณะสัมผัสลูกแก้วคริสตัลนี้ คุณสามารถร่ายคาถา _Scrying_ (Save DC 17) ได้ และคุณจะมีสายตาสัจธรรมแห่งความจริง (Truesight) ในระยะ 120 ฟุตผ่านจุดเซนเซอร์สอดแนม', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('cube_of_force', 'Cube of Force', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Rare (Requires Attunement)_\n\nลูกบาศก์ขนาดประมาณ 1 นิ้วที่มีสัญลักษณ์บนแต่ละหน้า มีพลังงาน 36 ชาร์จ คุณสามารถกดหน้าต่างๆ เพื่อสร้างม่านพลังบาเรียทรงลูกบาศก์ขนาด 15 ฟุตรอบตัวคุณที่สามารถกันก๊าซ ลม ของเหลว วัตถุ สิ่งมีชีวิต หรือพลังเวทมนตร์ได้ตามต้องการ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('cubic_gate', 'Cubic Gate', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Legendary_\n\nลูกบาศก์ขนาด 3 นิ้วที่มีพลังเวทมนตร์แผ่ออกมา แต่ละด้านเชื่อมโยงกับมิติอื่น (Plane of Existence) หนึ่งมิติ (รวมถึง Material Plane) คุณสามารถกดเพื่อร่ายคาถา _Plane Shift_ หรือเปิดประตูมิติ (Gate) ไปยังมิติดังกล่าวได้ มี 3 ชาร์จต่อวัน', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('dagger', 'Dagger', NULL, 'Weapon', 'Simple Melee', 'None', '2 GP', '1', NULL, '1d4 Piercing', 'Nick', 'Finesse, Light, Thrown (Range 20/60)', NULL, NULL, NULL, 'มีดสั้นปลายแหลมพร้อมคมดาบทั้งสองด้าน ออกแบบมาเพื่อการแทงและการขว้างอย่างแม่นยำ (Simple Melee, สร้างความเสียหาย Piercing 1d4, คุณสมบัติ: Finesse, Light, Thrown ระยะ 20/60, Mastery: Nick, น้ำหนัก: 1 ปอนด์, ราคา: 2 GP)', '{\"logic\":{\"weapon_category\":\"Simple\",\"damage_dice\":\"1d4\",\"damage_type\":\"Piercing\",\"properties\":[\"Finesse\",\"Light\",\"Thrown\"],\"range\":{\"normal\":20,\"long\":60},\"mastery_id\":\"nick\"},\"display\":\"1d4 Piercing | Finesse, Light, Thrown (Range 20\\/60) | Mastery: Nick\",\"modifiers\":[]}', 'SRD 5.2.1, Page 91', 0, NULL, NULL),
('dagger-of-venom', 'Dagger of Venom', NULL, 'Magic Item', 'Weapon', 'Rare', NULL, '1', NULL, '1d4 Piercing', 'Nick', 'Finesse, Light, Thrown', NULL, NULL, NULL, '<p>คุณจะได้รับโบนัส +1 ในการทอยโจมตีและทอยความเสียหาย คุณสามารถใช้โบนัสแอ็กชันเพื่อเคลือบใบมีดด้วยพิษร้ายสีดำ เมื่อโจมตีโดนเป้าหมาย เป้าหมายต้องผ่านการทอยเซฟ DC 15 Constitution มิฉะนั้นจะได้รับความเสียหาย Poison 2d10 และติดสถานะ Poisoned เป็นเวลา 1 นาที ใช้ได้วันละครั้ง</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 216', 0, NULL, NULL),
('damage_threshold', 'Damage Threshold', NULL, 'Gear', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ขีดจำกัดความเสียหาย (Damage Threshold): หากยานพาหนะหรือวัตถุมีค่านี้ ความเสียหายใดๆ ที่ได้รับในการโจมตีครั้งเดียวจะต้องมากกว่าหรือเท่ากับค่านี้จึงจะสร้างความเสียหายแก่วัตถุได้ หากความเสียหายต่ำกว่าค่านี้ วัตถุจะไม่ได้รับความเสียหายเลย', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('dancing_sword', 'Dancing Sword', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Weapon (Greatsword, Longsword, Rapier, Scimitar, or Shortsword), Very Rare (Requires Attunement)_\n\nคุณสามารถใช้โบนัสแอ็กชันเพื่อโยนดาบเวทมนตร์นี้ขึ้นสู่อากาศ ดาบจะลอยร่ายรำและโจมตีศัตรูในระยะ 30 ฟุตจากคุณตามคำสั่งประหนึ่งว่าคุณถือมันฟันด้วยตนเองเป็นเวลา 4 เทิร์น', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('dart', 'Dart', NULL, 'Weapon', 'Simple Ranged', 'None', '5 CP', '0.25', NULL, '1d4 Piercing', 'Vex', 'Finesse, Thrown (Range 20/60)', NULL, NULL, NULL, 'อาวุธ Simple Ranged สร้างความเสียหาย Piercing (แทง) 1d4 คุณสมบัติ: Finesse (คล่องแคล่ว), Thrown (ขว้าง ระยะ 20/60 ฟุต) ความชำนาญอาวุธ (Weapon Mastery): Vex น้ำหนัก: 1/4 ปอนด์, ราคา: 5 CP', '{\"logic\":{\"weapon_category\":\"Simple\",\"damage_dice\":\"1d4\",\"damage_type\":\"Piercing\",\"range\":{\"normal\":20,\"long\":60},\"properties\":[\"Finesse\",\"Thrown\"],\"mastery_id\":\"vex\"},\"display\":\"1d4 Piercing | Finesse, Thrown (Range 20\\/60) | Mastery: Vex\",\"modifiers\":[]}', 'SRD 5.2.1, Page 91', 0, NULL, NULL),
('decanter-of-endless-water', 'Decanter of Endless Water', NULL, 'Magic Item', 'Wondrous Item', 'Uncommon', NULL, '2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>คนโทน้ำไร้ขีดจำกัด คุณสามารถเปิดจุกแล้วใช้แอ็กชัน Magic พูดคำสั่งเพื่อปล่อยน้ำออกมา: สายน้ำพวยพุ่ง (Stream: 1 แกลลอน), น้ำพุพุ่งแรง (Fountain: 5 แกลลอน) หรือเสาน้ำแรงดันสูง (Geyser: 30 แกลลอน กระแทกศัตรูให้ล้มและสร้างความเสียหาย Bludgeoning 1d4)</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 217', 0, NULL, NULL),
('deck_of_illusions', 'Deck of Illusions', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon_\n\nกล่องบรรจุสำรับไพ่ 34 ใบ เมื่อคุณสุ่มจั่วไพ่แล้วขว้างลงบนพื้นในระยะ 30 ฟุต ไพ่จะสร้างภาพลวงตาของสิ่งมีชีวิตที่เหมือนจริงขึ้นมา เช่น มังกรแดง, โกเลมเหล็ก หรือนักรบ ภาพลวงตาจะขยับเคลื่อนไหวได้แต่สร้างความเสียหายไม่ได้', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('defender', 'Defender', NULL, 'Magic Item', 'Weapon', 'Legendary', NULL, '0', 'Requires Attunement', NULL, NULL, NULL, NULL, NULL, NULL, '<p>คุณจะได้รับโบนัส +3 ในการทอยโจมตีและทอยความเสียหายด้วยอาวุธนี้ ในแต่ละเทิร์นของคุณ คุณสามารถเลือกโอนถ่ายโบนัสบางส่วนหรือทั้งหมด (+1, +2 หรือ +3) ไปเพิ่มให้แก่ค่า Armor Class (AC) ของคุณแทนได้จนกว่าจะเริ่มเทิร์นถัดไป</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 218', 0, NULL, NULL),
('demon_armor', 'Demon Armor', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Armor (Any Light, Medium, or Heavy), Very Rare (Requires Attunement)_\n\nขณะสวมชุดเกราะนี้ คุณจะได้รับโบนัส +1 ใน Armor Class และเข้าใจภาษา Abyssal กรงเล็บของเกราะถือเป็นอาวุธเวทมนตร์ที่สร้างความเสียหาย Slashing 1d8 (+1 โจมตีและดาเมจ) แต่ชุดเกราะติดคำสาปทำให้คุณติด Disadvantage ในการทอยโจมตีต้านทานปีศาจ (Demons)', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('dice', 'Dice', NULL, 'Tool', 'Gaming Set', 'None', '1 SP', '', '', '', '', 'Ability: Wisdom', '', '', '', '**ความสามารถ (Ability):** Wisdom (ประเภทชุดเกมเสี่ยงโชค Gaming Set)\n\n**การใช้งาน (Utilize):** สังเกตว่ามีผู้ใดโกงการเล่นหรือไม่ (DC 10) หรือเอาชนะเกม (DC 20)', '{\"logic\":{\"tool_type\":\"Gaming Set\",\"ability\":\"Wisdom\",\"utilize\":\"Discern whether someone is cheating (DC 10), or win the game (DC 20)\"},\"display\":\"Ability: Wisdom | Variant of Gaming Set\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('dimensional_shackles', 'Dimensional Shackles', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Rare_\n\nคุณสามารถใช้แอ็กชัน Utilize เพื่อสวมกุญแจมือนี้ให้แก่สิ่งมีชีวิตที่ติดสภาวะ Incapacitated กุญแจมือจะปรับขนาดให้พอดีกับสิ่งมีชีวิตขนาด Small ถึง Large และป้องกันไม่ให้สิ่งมีชีวิตนั้นใช้การเทเลพอร์ตหรือการเดินทางข้ามมิติทุกรูปแบบ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('diplomat_s_pack', 'Diplomat\'s Pack', NULL, 'Pack', NULL, 'None', '39 GP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Diplomat\'s Pack ประกอบด้วย: หีบไม้ (Chest), เสื้อผ้าชั้นดี 2 ชุด (Fine Clothes), น้ำหมึก 1 ขวด (Ink), ปากกาขนนก 5 ด้าม (Ink Pens), ตะเกียง (Lamp), กระบอกใส่แผนที่หรือม้วนคัมภีร์ 2 กระบอก (Map or Scroll Cases), น้ำมัน 4 ขวด (Oil), กระดาษ 5 แผ่น (Paper), กระดาษหนัง 5 แผ่น (Parchment), น้ำหอม 1 ขวด (Perfume) และชุดจุดไฟ (Tinderbox)', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('disguise-kit', 'Disguise Kit', NULL, 'Tool', 'Kit', 'None', '25 GP', '3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p><b>ความสามารถ (Ability):</b> Charisma<br><b>การใช้งาน (Utilize):</b> แต่งหน้าแปลงโฉม (DC 10)<br><b>การสร้าง (Craft):</b> ชุดคอสตูมปลอมตัว (Costume)</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 94', 0, NULL, NULL),
('disguise_kit', 'Disguise Kit', NULL, 'Tool', 'Tool', 'None', '25 GP', '3 lb.', '', '', '', 'Ability: Charisma', '', '', '', '**ความสามารถ (Ability):** Charisma\n\n**การใช้งาน (Utilize):** แต่งหน้าแปลงโฉม (DC 10)\n\n**การสร้าง (Craft):** ชุดคอสตูมปลอมตัว (Costume)', '{\"logic\":{\"tool_type\":\"Tool\",\"ability\":\"Charisma\",\"utilize\":\"Apply makeup (DC 10)\",\"craft\":\"Costume\"},\"display\":\"Ability: Charisma | Craft: Costume\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('draft-horse', 'Draft Horse', NULL, 'Mount', 'Animal', 'None', '50 GP', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>ความจุในการบรรทุก (Carrying Capacity): 540 ปอนด์ ความเร็ว (Speed): 40 ฟุต</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 100', 0, NULL, NULL),
('dragonchess', 'Dragonchess', NULL, 'Tool', 'Gaming Set', 'None', '1 GP', '', '', '', '', 'Ability: Wisdom', '', '', '', '**ความสามารถ (Ability):** Wisdom (ประเภทชุดเกม Gaming Set)\n\n**การใช้งาน (Utilize):** สังเกตว่ามีผู้ใดโกงการเล่นหรือไม่ (DC 10) หรือเอาชนะเกมหมากรุกมังกร (DC 20)', '{\"logic\":{\"tool_type\":\"Gaming Set\",\"ability\":\"Wisdom\",\"utilize\":\"Discern whether someone is cheating (DC 10), or win the game (DC 20)\"},\"display\":\"Ability: Wisdom | Variant of Gaming Set\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('dragon_orb', 'Dragon Orb', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Artifact (Requires Attunement)_\n\nลูกแก้วมังกรโบราณทรงพลังที่ผนึกดวงวิญญาณของมังกรเอาไว้ ผู้ครอบครองสามารถสื่อสารทางจิตกับมังกรในระยะไกล ร่ายคาถาอันทรงพลัง และเปรียบเสมือนสื่อนำทางในการสะกดจิตหรือเรียกมังกรให้มาหา', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('dragon_scale_mail', 'Dragon Scale Mail', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Armor (Scale Mail), Very Rare (Requires Attunement)_\n\nเกราะเกล็ดมังกรสร้างจากเกล็ดของมังกรสายพันธุ์ใดสายพันธุ์หนึ่ง คุณจะได้รับโบนัส +1 ใน Armor Class, มี Advantage ในการทอยเซฟต้านลมหายใจมังกรและความต้านทาน (Resistance) ต่อความเสียหายตามธาตุของมังกรชนิดนั้น และสามารถตรวจจับตำแหน่งมังกรในระยะ 30 ไมล์ได้', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('dragon_slayer', 'Dragon Slayer', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Weapon (Any Simple or Martial), Rare_\n\nคุณจะได้รับโบนัส +1 ในการทอยโจมตีและทอยความเสียหายด้วยอาวุธนี้ เมื่อคุณโจมตีโดนมังกร (Dragon) อาวุธจะสร้างความเสียหายเพิ่มเติมอีก 3d6 ตามประเภทความเสียหายของอาวุธ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('druidic_focus', 'Druidic Focus', NULL, 'Gear', NULL, 'None', 'Varies', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'สื่อร่ายเวทมนตร์สายธรรมชาติ (Druidic Focus) อาจเป็นกิ่งมิสเซิลโท, กระบองไม้ศักดิ์สิทธิ์, หรือเครื่องรางที่ทำจากกระดูกหรือหิน ใช้เป็นสื่อเหนี่ยวนำพลังเวทสำหรับ Druid และ Ranger', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('drum', 'Drum', NULL, 'Tool', 'Musical Instrument', 'None', '6 GP', '3 lb.', '', '', '', 'Ability: Charisma', '', '', '', '**ความสามารถ (Ability):** Charisma (ประเภทเครื่องดนตรี Musical Instrument)\n\n**การใช้งาน (Utilize):** บรรเลงบทเพลงที่รู้จัก (DC 10) หรือด้นสดแต่งทำนองใหม่ (DC 15)', '{\"logic\":{\"tool_type\":\"Musical Instrument\",\"ability\":\"Charisma\",\"utilize\":\"Play a known tune (DC 10), or improvise a song (DC 15)\"},\"display\":\"Ability: Charisma | Variant of Musical Instrument\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('dulcimer', 'Dulcimer', NULL, 'Tool', 'Musical Instrument', 'None', '25 GP', '10 lb.', '', '', '', 'Ability: Charisma', '', '', '', '**ความสามารถ (Ability):** Charisma (ประเภทเครื่องดนตรี Musical Instrument)\n\n**การใช้งาน (Utilize):** บรรเลงบทเพลงที่รู้จัก (DC 10) หรือด้นสดแต่งทำนองใหม่ (DC 15)', '{\"logic\":{\"tool_type\":\"Musical Instrument\",\"ability\":\"Charisma\",\"utilize\":\"Play a known tune (DC 10), or improvise a song (DC 15)\"},\"display\":\"Ability: Charisma | Variant of Musical Instrument\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('dungeoneers-pack', 'Dungeoneer\'s Pack', NULL, 'Pack', 'Equipment Pack', 'None', '12 GP', '55', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>ประกอบด้วย: กระเป๋าสะพาย (Backpack), กับดักหนามเท้า 20 ชิ้น (Caltrops), ชะแลง (Crowbar), น้ำมัน 2 ขวด (Oil), เสบียงอาหาร 10 วัน (Rations), เชือกป่าน 50 ฟุต (Rope), ชุดจุดไฟ (Tinderbox), คบเพลิง 10 เล่ม (Torches) และถุงใส่น้ำ (Waterskin)</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 97', 0, NULL, NULL),
('dust_of_disappearance', 'Dust of Disappearance', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon_\n\nผงทรายละเอียดสีเงิน คุณสามารถใช้แอ็กชัน Utilize สาดผงนี้ขึ้นไปในอากาศ คุณและสิ่งมีชีวิตทุกตัวพร้อมสัมภาระในระยะ 10 ฟุตจะล่องหนหายตัวไป (Invisible) เป็นเวลา 2d4 นาที การล่องหนนี้จะไม่หลุดออกแม้จะทำการโจมตีหรือร่ายคาถา', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('dust_of_dryness', 'Dust of Dryness', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon_\n\nผงดูดซับน้ำ เมื่อโปรยลงในน้ำ ผงจะดูดซับน้ำได้สูงสุดถึง 1,000 ลูกบาศก์ฟุตทันที และเปลี่ยนเป็นลูกแก้วขนาดเล็กที่บรรจุน้ำนั้นไว้ เมื่อทุบลูกแก้วแตก น้ำทั้งหมดจะไหลทะลักออกมาตามเดิม', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('dust_of_sneezing_and_choking', 'Dust of Sneezing and Choking', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon_\n\nผงที่ดูเหมือน _Dust of Disappearance_ แต่เมื่อสาดออกไป สิ่งมีชีวิตทุกตัวในระยะ 20 ฟุตที่หายใจต้องผ่านการทอยเซฟ DC 15 Constitution มิฉะนั้นจะจามและสำลักอย่างรุนแรง ติดสภาวะ Incapacitated และเริ่มหายใจไม่ออก', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('dwarven_plate', 'Dwarven Plate', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Armor (Half Plate Armor or Plate Armor), Very Rare_\n\nขณะสวมชุดเกราะหนาพิเศษของคนแคระนี้ คุณจะได้รับโบนัส +2 ใน Armor Class นอกจากนี้ หากมีผลลัพธ์ใดบังคับผลักคุณไปตามพื้น คุณสามารถใช้ Reaction เพื่อลดระยะการถูกผลักลงได้สูงสุด 10 ฟุต', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('dwarven_thrower', 'Dwarven Thrower', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Weapon (Warhammer), Very Rare (Requires Attunement by a Dwarf or a Creature Attuned to a Belt of Dwarvenkind)_\n\nคุณจะได้รับโบนัส +3 ในการทอยโจมตีและทอยความเสียหาย ค้อนศึกนี้มีคุณสมบัติ Thrown (ระยะ 20/60 ฟุต) และจะบินกลับมาเข้ามือคุณทันทีหลังโจมตี หากขว้างโจมตีโดนยักษ์ (Giant) จะสร้างความเสียหาย Bludgeoning เพิ่มเติมอีก 2d8', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('efficient_quiver', 'Efficient Quiver', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon_\n\nซองธนูวิเศษที่มีช่องกระเป๋าสามช่อง แต่ละช่องเชื่อมต่อกับมิติพิเศษ: ช่องแรกใส่ลูกธนูหรือกระสุนได้ถึง 60 ดอก, ช่องสองใส่วัตถุทรงยาวเช่นหอกหรือดอกหน้าไม้ได้ 18 ชิ้น, ช่องสามใส่วัตถุขนาดยาวเช่นคันธนูหรือไม้เท้าได้ 6 ชิ้น โดยซองจะมีน้ำหนักคงที่เพียง 2 ปอนด์เสมอ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('efreeti_bottle', 'Efreeti Bottle', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Very Rare_\n\nขวดทองเหลืองลงยันต์ เมื่อเปิดจุกออกจะมีควันหนาลอยพวยพุ่งและอัญเชิญยักษ์ไฟ Efreeti ออกมา โดยมีโอกาส 10% ที่ยักษ์จะโจมตีคุณ, 80% ที่ยักษ์จะรับใช้คุณเป็นเวลา 1 ชั่วโมง และ 10% ที่ยักษ์จะมอบพร 3 ประการดั่งคาถา _Wish_ ให้แก่คุณ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('elemental_gem', 'Elemental Gem', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon_\n\nอัญมณีที่ผนึกพลังธาตุเอาไว้ เมื่อคุณใช้แอ็กชัน Utilize บดหรือทุบอัญมณีให้แตก จะเป็นการอัญเชิญสิ่งมีชีวิตธาตุออกมาช่วยเหลือคุณตามสีของอัญมณี (สีน้ำเงิน: Water, สีแดง: Fire, สีเหลือง: Earth, สีฟ้า: Air) ประหนึ่งร่ายคาถา _Conjure Elemental_', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('elephant', 'Elephant', NULL, 'Mount', 'Mount', 'None', '200 GP', '', '', '', '', 'Carrying Capacity: 1,320 lb.', '', '', '', 'ความจุในการบรรทุก (Carrying Capacity): 1,320 ปอนด์ ความเร็ว (Speed): 40 ฟุต', '{\"logic\":{\"carrying_capacity\":\"1,320 lb.\"},\"display\":\"Carrying Capacity: 1,320 lb.\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('elixir-of-health', 'Elixir of Health', NULL, 'Magic Item', 'Potion', 'Rare', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>เมื่อคุณดื่มน้ำยานี้ โรคภัยไข้เจ็บและพิษเวทมนตร์ทั้งหมดในร่างกายคุณจะได้รับการรักษา และสถานะ Blinded, Deafened, Paralyzed และ Poisoned จะสิ้นสุดลงทันที</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 220', 0, NULL, NULL),
('elven_chain', 'Elven Chain', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Armor (Chain Mail or Chain Shirt), Rare_\n\nคุณจะได้รับโบนัส +1 ใน Armor Class ขณะสวมเกราะโซ่ถักของเอลฟ์นี้ นอกจากนี้ คุณถือว่ามีความชำนาญ (Proficient) ในการสวมใส่เกราะนี้โดยอัตโนมัติแม้ว่าคลาสของคุณจะไม่มีความชำนาญในชุดเกราะประเภทนี้ก็ตาม', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('ending_attunement', 'Ending Attunement', NULL, 'Gear', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'การผูกพัน (Attunement) กับไอเทมเวทมนตร์จะสิ้นสุดลงหากคุณไม่ผ่านเงื่อนไขของไอเทมนั้นอีกต่อไป, ไอเทมห่างจากตัวคุณเกิน 100 ฟุตเป็นเวลาอย่างน้อย 24 ชั่วโมง, คุณเสียชีวิต, หรือคุณใช้เวลาช่วง Short Rest เพื่อปลดการผูกพัน', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('energy_bow', 'Energy Bow', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Weapon (Longbow or Shortbow), Very Rare (Requires Attunement)_\n\nคุณจะได้รับโบนัส +1 ในการทอยโจมตีและทอยความเสียหายด้วยคันธนูพลังงานนี้ คันธนูไม่จำเป็นต้องใช้ลูกธนูปกติ เมื่อคุณง้างสายธนู มันจะสร้างลูกศรแสงเลเซอร์เวทมนตร์ขึ้นมาเองและสร้างความเสียหาย Radiant', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('entertainer_s_pack', 'Entertainer\'s Pack', NULL, 'Pack', NULL, 'None', '40 GP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Entertainer\'s Pack ประกอบด้วย: กระเป๋าสะพาย (Backpack), ถุงนอน (Bedroll), กระดิ่ง (Bell), ตะเกียงส่องลำแสง (Bullseye Lantern), ชุดเครื่องแต่งกายการแสดง 3 ชุด (Costumes), กระจกเหล็ก (Mirror), น้ำมัน 8 ขวด (Oil), เสบียงอาหาร 9 วัน (Rations), ชุดจุดไฟ (Tinderbox) และถุงใส่น้ำ (Waterskin)', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('eversmoking_bottle', 'Eversmoking Bottle', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon_\n\nเมื่อเปิดจุกขวดออก กลุ่มควันหนาทึบจะพวยพุ่งออกมาปกคลุมพื้นที่รัศมี 60 ฟุตทันที และแผ่ขยายออกไปอีก 10 ฟุตในทุกๆ นาทีจนครอบคลุมรัศมีสูงสุด 120 ฟุต ทำให้พื้นที่กลายเป็นบดบังการมองเห็นอย่างสมบูรณ์ (Heavily Obscured)', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('exotic', 'Exotic', NULL, 'Vehicle', 'Land Vehicle / Harness', 'None', '60 GP', '40 lb.', '', '', '', '', '', '', '', 'อานม้าหรืออุปกรณ์เทียมสัตว์สำหรับสัตว์พาหนะแปลกตาหรือสัตว์วิเศษ (Exotic Saddle)', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('explorers-pack', 'Explorer\'s Pack', NULL, 'Pack', 'Equipment Pack', 'None', '10 GP', '55', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p>ประกอบด้วย: กระเป๋าสะพาย (Backpack), ถุงนอน (Bedroll), น้ำมัน 2 ขวด (Oil), เสบียงอาหาร 10 วัน (Rations), เชือกป่าน 50 ฟุต (Rope), ชุดจุดไฟ (Tinderbox), คบเพลิง 10 เล่ม (Torches) และถุงใส่น้ำ (Waterskin)</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 97', 0, NULL, NULL),
('eyes_of_charming', 'Eyes of Charming', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon (Requires Attunement)_\n\nเลนส์แว่นตาคริสตัล มี 3 ชาร์จ ขณะสวมใส่ คุณสามารถใช้แอ็กชัน Magic สบตากับสิ่งมีชีวิตในระยะ 30 ฟุตและใช้ 1 ชาร์จเพื่อร่ายคาถา _Charm Person_ (Save DC 13)', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('eyes_of_minute_seeing', 'Eyes of Minute Seeing', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon_\n\nเลนส์แว่นตานี้ช่วยเพิ่มสายตาในการเพ่งมองระยะใกล้ 1 ฟุตอย่างละเอียด มอบ Advantage ในการทอย Investigation checks เพื่อตรวจสอบสิ่งของขนาดจิ๋วหรือกลไกกับดัก', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('eyes_of_the_eagle', 'Eyes of the Eagle', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon_\n\nเลนส์แว่นตาสายตาอินทรี มอบ Advantage ในการทอย Wisdom (Perception) check ที่อาศัยการมองเห็น และช่วยให้คุณมองเห็นสิ่งต่างๆ ในระยะไกลได้อย่างคมชัดประหนึ่งอยู่ตรงหน้า', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('feather_token', 'Feather Token', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Rarity Varies_\n\nเหรียญขนนกวิเศษสำหรับใช้งานครั้งเดียว มีหลากหลายรูปแบบ เช่น Anchor (ทอดสมอเรือให้หยุดนิ่ง), Bird (ส่งข้อความระยะไกล), Fan (สร้างลมแรงพัดใบเรือ), Swan Boat (กลายร่างเป็นเรือหงส์ขนาดใหญ่) หรือ Tree (งอกเป็นต้นโอ๊กยักษ์สูง 60 ฟุตทันที)', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('feed_per_day', 'Feed per day', NULL, 'Vehicle', 'Land Vehicle / Harness', 'None', '5 CP', '10 lb.', '', '', '', '', '', '', '', 'อาหารสัตว์พาหนะต่อหนึ่งวัน (Feed per day)', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('figurine_of_wondrous_power', 'Figurine of Wondrous Power', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Rarity Varies_\n\nรูปปั้นสัตว์ขนาดเล็กพอที่จะใส่ในกระเป๋าได้ เมื่อคุณขว้างรูปปั้นลงบนพื้นและเอ่ยคำสั่ง มันจะกลายร่างเป็นสัตว์อสูรที่มีชีวิตขึ้นมาคอยช่วยเหลือและเชื่อฟังคำสั่งของคุณเป็นเวลาตามที่กำหนด (เช่น Bronze Griffon, Ebony Fly, Golden Lions, Ivory Goats, Marble Elephant หรือ Onyx Dog)', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('flail', 'Flail', NULL, 'Weapon', 'Martial Melee', 'None', '10 GP', '2', NULL, '1d8 Bludgeoning', 'Sap', NULL, NULL, NULL, NULL, 'อาวุธ Martial Melee สร้างความเสียหาย Bludgeoning (ทุบ) 1d8 คุณสมบัติ: — ความชำนาญอาวุธ (Weapon Mastery): Sap น้ำหนัก: 2 ปอนด์, ราคา: 10 GP', '{\"logic\":{\"weapon_category\":\"Martial\",\"damage_dice\":\"1d8\",\"damage_type\":\"Bludgeoning\",\"properties\":[],\"mastery_id\":\"sap\"},\"display\":\"1d8 Bludgeoning | Mastery: Sap\",\"modifiers\":[]}', 'SRD 5.2.1, Page 91', 0, NULL, NULL),
('flame-tongue', 'Flame Tongue', NULL, 'Magic Item', 'Weapon', 'Rare', NULL, '0', 'Requires Attunement', NULL, NULL, NULL, NULL, NULL, NULL, '<p>คุณสามารถใช้โบนัสแอ็กชันเอ่ยคำสั่งเพื่อให้ใบดาบลุกเป็นเปลวเพลิง เมื่อติดไฟ ดาบจะส่องสว่างระดับ Bright Light ในระยะ 40 ฟุต และสร้างความเสียหาย Fire เพิ่มเติมอีก 2d6 เมื่อโจมตีโดนเป้าหมาย</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 223', 0, NULL, NULL),
('flask', 'Flask', NULL, 'Gear', NULL, 'None', '2 CP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ขวดเหล้าพกพาโลหะหรือแก้วหนา บรรจุของเหลวได้สูงสุด 1 ไพนต์ (ประมาณ 0.5 ลิตร)', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('flute', 'Flute', NULL, 'Tool', 'Musical Instrument', 'None', '2 GP', '1 lb.', '', '', '', 'Ability: Charisma', '', '', '', '**ความสามารถ (Ability):** Charisma (ประเภทเครื่องดนตรี Musical Instrument)\n\n**การใช้งาน (Utilize):** บรรเลงบทเพลงที่รู้จัก (DC 10) หรือด้นสดแต่งทำนองใหม่ (DC 15)', '{\"logic\":{\"tool_type\":\"Musical Instrument\",\"ability\":\"Charisma\",\"utilize\":\"Play a known tune (DC 10), or improvise a song (DC 15)\"},\"display\":\"Ability: Charisma | Variant of Musical Instrument\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('folding_boat', 'Folding Boat', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Rare_\n\nกล่องไม้ขนาดกว้าง 6 นิ้ว ยาว 12 นิ้ว เมื่อเอ่ยคำสั่งแรก กล่องจะกางออกกลายเป็นเรือพาย (Rowboat) ยาว 10 ฟุต และเมื่อเอ่ยคำสั่งที่สอง จะกางขยายเป็นเรือใบ (Sailing Ship) ยาว 24 ฟุตพร้อมเสากระโดงและหางเสือ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('forgery-kit', 'Forgery Kit', NULL, 'Tool', 'Kit', 'None', '15 GP', '5', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '<p><b>ความสามารถ (Ability):</b> Dexterity<br><b>การใช้งาน (Utilize):</b> ลอกเลียนลายมือของผู้อื่นไม่เกิน 10 คำ (DC 15) หรือทำตราประทับขี้ผึ้งจำลอง (DC 20)</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 94', 0, NULL, NULL),
('forgery_kit', 'Forgery Kit', NULL, 'Tool', 'Tool', 'None', '15 GP', '5 lb.', '', '', '', 'Ability: Dexterity', '', '', '', '**ความสามารถ (Ability):** Dexterity\n\n**การใช้งาน (Utilize):** ลอกเลียนลายมือของผู้อื่นไม่เกิน 10 คำ (DC 15) หรือทำตราประทับขี้ผึ้งจำลอง (DC 20)', '{\"logic\":{\"tool_type\":\"Tool\",\"ability\":\"Dexterity\",\"utilize\":\"Mimic 10 or fewer words of someone else\'s handwriting (DC 15), or duplicate a wax seal (DC 20)\",\"craft\":\"\"},\"display\":\"Ability: Dexterity\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('frost_brand', 'Frost Brand', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Weapon (Glaive, Greatsword, Longsword, Rapier, Scimitar, or Shortsword), Very Rare (Requires Attunement)_\n\nเมื่อคุณโจมตีโดนด้วยอาวุธนี้ อาวุธจะสร้างความเสียหาย Cold เพิ่มเติมอีก 1d6 ขณะถืออาวุธ คุณจะมีความต้านทานต่อความเสียหาย Fire และในอุณหภูมิต่ำกว่าจุดเยือกแข็ง อาวุธจะส่องแสงสว่างสีฟ้าเรืองรอง', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('galley', 'Galley', NULL, 'Vehicle', 'Waterborne/Airborne Vehicle', 'None', '30,000 GP', '', '', '', '', 'Speed: 4 mph', '15', '', '', 'ความเร็ว (Speed): 4 ไมล์/ชม. | ลูกเรือ (Crew): 80 คน | ผู้โดยสาร: — | บรรทุกสัมภาระ (Cargo): 150 ตัน | AC: 15 | HP: 500 | ขีดจำกัดความเสียหาย (Damage Threshold): 20', '{\"logic\":{\"speed\":\"4 mph\",\"crew\":\"80\",\"passengers\":\"—\",\"cargo\":\"150\",\"ac\":\"15\",\"hp\":\"500\"},\"display\":\"Speed: 4 mph | AC: 15 | HP: 500\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('gaming_set', 'Gaming Set', NULL, 'Tool', 'Tool', 'None', 'Varies', '', '', '', '', 'Ability: Wisdom', '', '', '', '**ความสามารถ (Ability):** Wisdom\n\n**การใช้งาน (Utilize):** สังเกตว่ามีผู้ใดโกงการเล่นหรือไม่ (DC 10) หรือเอาชนะการเล่นเกม (DC 20)', '{\"logic\":{\"tool_type\":\"Tool\",\"ability\":\"Wisdom\",\"utilize\":\"Discern whether someone is cheating (DC 10), or win the game (DC 20)\",\"craft\":\"\"},\"display\":\"Ability: Wisdom\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('gauntlets-of-ogre-power', 'Gauntlets of Ogre Power', NULL, 'Magic Item', 'Wondrous Item', 'Uncommon', NULL, '0', 'Requires Attunement', NULL, NULL, NULL, NULL, NULL, NULL, '<p>ค่าพละกำลัง (Strength) ของคุณจะกลายเป็น 19 ขณะที่คุณสวมถุงมือคู่นี้ ถุงมือจะไม่มีผลหากค่า Strength ตามปกติของคุณเท่ากับหรือมากกว่า 19 อยู่แล้ว</p>', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', 'SRD 5.2.1, Page 223', 0, NULL, NULL),
('gem_of_brightness', 'Gem of Brightness', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon_\n\nปริซึมอัญมณี มี 50 ชาร์จ คุณสามารถใช้แอ็กชัน Magic สั่งให้ส่องลำแสงจ้า: ลำแสงส่องทาง 60 ฟุต (1 ชาร์จ), ลำแสงสว่างจ้าทำให้เป้าหมายตาบอด Blinded (1 ชาร์จ, DC 15 Con save) หรือระเบิดแสงรอบทิศทางทำให้ศัตรูในระยะ 30 ฟุตตาบอด (5 ชาร์จ)', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('gem_of_seeing', 'Gem of Seeing', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Rare (Requires Attunement)_\n\nอัญมณีแห่งการมองเห็น มี 3 ชาร์จ คุณสามารถใช้แอ็กชัน Magic และใช้ 1 ชาร์จเพื่อมองผ่านอัญมณี มอบสายตาสัจธรรมแห่งความจริง (Truesight) ในระยะ 120 ฟุตเป็นเวลา 10 นาที', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('giant_fly', 'Giant Fly', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Large Beast, Unaligned_\n\n**AC** 11 **Initiative** +1 (11) <br>\n**HP** 19 (3d10 + 3) <br>\n**Speed** 30 ฟุต, บิน 60 ฟุต <br>\n\nแมลงวันยักษ์ที่ถูกอัญเชิญมาจากรูปปั้น Ebony Fly สามารถใช้เป็นสัตว์พาหนะบินได้สำหรับสิ่งมีชีวิตขนาด Medium หรือเล็กกว่า', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('giant_slayer', 'Giant Slayer', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Weapon (Any Simple or Martial), Rare_\n\nคุณจะได้รับโบนัส +1 ในการทอยโจมตีและทอยความเสียหายด้วยอาวุธนี้ เมื่อคุณโจมตีโดนสิ่งมีชีวิตประเภท Giant อาวุธจะสร้างความเสียหายเพิ่มเติมอีก 2d6 และยักษ์ต้องผ่านการทอยเซฟ DC 15 Strength มิฉะนั้นจะล้มลงติดสถานะ Prone', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('glaive', 'Glaive', NULL, 'Weapon', 'Martial Melee', 'None', '20 GP', '6', NULL, '1d10 Slashing', 'Graze', 'Heavy, Reach, Two-Handed', NULL, NULL, NULL, 'อาวุธ Martial Melee สร้างความเสียหาย Slashing (ฟัน) 1d10 คุณสมบัติ: Heavy (หนัก), Reach (ระยะเอื้อมไกล), Two-Handed (สองมือ) ความชำนาญอาวุธ (Weapon Mastery): Graze น้ำหนัก: 6 ปอนด์, ราคา: 20 GP', '{\"logic\":{\"weapon_category\":\"Martial\",\"damage_dice\":\"1d10\",\"damage_type\":\"Slashing\",\"properties\":[\"Heavy\",\"Reach\",\"Two-Handed\"],\"mastery_id\":\"graze\"},\"display\":\"1d10 Slashing | Heavy, Reach, Two-Handed | Mastery: Graze\",\"modifiers\":[]}', 'SRD 5.2.1, Page 91', 0, NULL, NULL),
('glamoured_studded_leather', 'Glamoured Studded Leather', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Armor (Studded Leather Armor), Rare_\n\nขณะสวมชุดเกราะนี้ คุณจะได้รับโบนัส +1 ใน Armor Class คุณยังสามารถใช้โบนัสแอ็กชันเพื่อสั่งให้ชุดเกราะเปลี่ยนรูปลักษณ์ภายนอกกลายเป็นเสื้อผ้าธรรมดาหรือชุดเกราะประเภทอื่นได้ตามใจนึก โดยคุณสมบัติและน้ำหนักของเกราะยังคงเดิมจนกว่าคุณจะเปลี่ยนใหม่หรือถอดออก', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('glassblowers_tools', 'Glassblower\'s Tools', NULL, 'Tool', 'Tool', 'None', '30 GP', '5 lb.', '', '', '', 'Ability: Intelligence', '', '', '', '**ความสามารถ (Ability):** Intelligence\n\n**การใช้งาน (Utilize):** ตรวจสอบว่าภาชนะแก้วชิ้นนั้นเคยบรรจุสิ่งใดมาในรอบ 24 ชั่วโมงที่ผ่านมา (DC 15)\n\n**การสร้าง (Craft):** ขวดแก้ว (Glass Bottle), แว่นขยาย (Magnifying Glass), กล้องส่องทางไกล (Spyglass), ขวดหลอดแก้ว (Vial)', '{\"logic\":{\"tool_type\":\"Tool\",\"ability\":\"Intelligence\",\"utilize\":\"Discern what a glass object held in the past 24 hours (DC 15)\",\"craft\":\"Glass Bottle, Magnifying Glass, Spyglass, Vial\"},\"display\":\"Ability: Intelligence | Craft: Glass Bottle, Magnifying Glass, Spyglass, Vial\",\"modifiers\":[]}', 'SRD 2024', 0, NULL, NULL),
('gloves_of_missile_snaring', 'Gloves of Missile Snaring', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon (Requires Attunement)_\n\nหากคุณถูกโจมตีโดนด้วยอาวุธโจมตีระยะไกล (Ranged หรือ Thrown weapon) ขณะสวมถุงมือคู่นี้ คุณสามารถใช้ Reaction เพื่อลดความเสียหายที่ได้รับลง 1d10 + ตัวปรับแต่ง Dexterity ของคุณ หากคุณลดความเสียหายลงจนเหลือ 0 คุณสามารถคว้าจับอาวุธหรือกระสุนนั้นไว้ได้หากมือของคุณว่าง', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('gloves_of_swimming_and_climbing', 'Gloves of Swimming and Climbing', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon (Requires Attunement)_\n\nขณะสวมถุงมือคู่นี้ คุณจะมีความเร็วในการปีนป่าย (Climb Speed) และความเร็วในการว่ายน้ำ (Swim Speed) เท่ากับความเร็วในการเดินของคุณ และคุณจะได้รับ Advantage ในการทอย Strength (Athletics) checks ที่เกี่ยวกับการปีนป่ายหรือการว่ายน้ำ', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('gloves_of_thievery', 'Gloves of Thievery', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon_\n\nถุงมือที่โปร่งใสแนบเนียนไปกับผิวหนังจนมองไม่เห็นเมื่อสวมใส่ ขณะสวมใส่ คุณจะได้รับโบนัส +5 ในการทอย Dexterity (Sleight of Hand) checks และการทอยตรวจสอบเพื่อสะเดาะกลอนกุญแจด้วย Thieves\' Tools', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('goggles_of_night', 'Goggles of Night', NULL, 'Magic Item', NULL, 'None', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '_Wondrous Item, Uncommon_\n\nขณะสวมแว่นตาดำคู่นี้ คุณจะมีสายตามองในที่มืด (Darkvision) ในระยะ 60 ฟุต หากคุณมี Darkvision อยู่แล้ว แว่นตานี้จะเพิ่มระยะขึ้นอีก 60 ฟุต', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('grappling_hook', 'Grappling Hook', NULL, 'Gear', NULL, 'None', '2 GP', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'คุณสามารถใช้แอ็กชัน Utilize เพื่อขว้างตะขอเกี่ยวไปเกาะกับขอบกำแพง ราว หรือเหลี่ยมหินในระยะไม่เกินความยาวของเชือกที่คุณผูกติดไว้', '{\"logic\":[],\"display\":\"\",\"modifiers\":[]}', NULL, 0, NULL, NULL),
('greataxe', 'Greataxe', NULL, 'Weapon', 'Martial Melee', 'None', '30 GP', '7', NULL, '1d12 Slashing', 'Cleave', 'Heavy, Two-Handed', NULL, NULL, NULL, 'อาวุธ Martial Melee สร้างความเสียหาย Slashing (ฟัน) 1d12 คุณสมบัติ: Heavy (หนัก), Two-Handed (สองมือ) ความชำนาญอาวุธ (Weapon Mastery): Cleave น้ำหนัก: 7 ปอนด์, ราคา: 30 GP', '{\"logic\":{\"weapon_category\":\"Martial\",\"damage_dice\":\"1d12\",\"damage_type\":\"Slashing\",\"properties\":[\"Heavy\",\"Two-Handed\"],\"mastery_id\":\"cleave\"},\"display\":\"1d12 Slashing | Heavy, Two-Handed | Mastery: Cleave\",\"modifiers\":[]}', 'SRD 5.2.1, Page 91', 0, NULL, NULL),
('greatclub', 'Greatclub', NULL, 'Weapon', 'Simple Melee', 'None', '2 SP', '10', NULL, '1d8 Bludgeoning', 'Push', 'Two-Handed', NULL, NULL, NULL, 'อาวุธ Simple Melee สร้างความเสียหาย Bludgeoning (ทุบ) 1d8 คุณสมบัติ: Two-Handed (สองมือ) ความชำนาญอาวุธ (Weapon Mastery): Push น้ำหนัก: 10 ปอนด์, ราคา: 2 SP', '{\"logic\":{\"weapon_category\":\"Simple\",\"damage_dice\":\"1d8\",\"damage_type\":\"Bludgeoning\",\"properties\":[\"Two-Handed\"],\"mastery_id\":\"push\"},\"display\":\"1d8 Bludgeoning | Two-Handed | Mastery: Push\",\"modifiers\":[]}', 'SRD 5.2.1, Page 91', 0, NULL, NULL),
